  const sep = separator.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  let slug = stripAccents(str)
    .replace(/&/g, ' and ')           // Make "&" readable
    .replace(/['’]/g, '')             // Drop apostrophes so "it's" -> "its"
    .replace(/[^A-Za-z0-9]+/g, separator) // Non-alphanumerics -> separator
    .replace(new RegExp(`${sep}{2,}`, 'g'), separator) // Collapse repeats
    .replace(new RegExp(`^${sep}|${sep}$`, 'g'), '');   // Trim ends

