# ISO-8601 Date Utilities

```javascript
// iso8601.js
// Utilities for formatting and parsing ISO-8601 dates.

const ISO_REGEX = new RegExp(
  '^' +
    '([+-]\\d{6}|\\d{4})' +              // 1: year (4 digits, or signed 6-digit expanded year)
    '-(\\d{2})' +                        // 2: month
    '-(\\d{2})' +                        // 3: day
    '(?:' +
      '[Tt ](\\d{2})' +                  // 4: hour
      ':(\\d{2})' +                      // 5: minute
      '(?::(\\d{2})' +                   // 6: second
        '(?:[.,](\\d{1,9}))?' +          // 7: fractional seconds
      ')?' +
      '([Zz]|[+-]\\d{2}(?::?\\d{2})?)?' + // 8: timezone designator
    ')?' +
  '$'
);

function pad(num, length) {
  return String(Math.abs(num)).padStart(length, '0');
}

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year, month) {
  return [31, isLeapYear(year) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
}

function formatYear(year) {
  if (year >= 0 && year <= 9999) return pad(year, 4);
  return (year < 0 ? '-' : '+') + pad(year, 6);
}

function toDate(value) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`formatDate: invalid date: ${String(value)}`);
  }
  return date;
}

/**
 * Format a Date as an ISO-8601 string.
 *
 * @param {Date|number} date - A Date object or millisecond timestamp.
 * @param {Object} [options]
 * @param {boolean} [options.dateOnly=false] - Output only "YYYY-MM-DD".
 * @param {boolean} [options.local=false] - Use local time with a numeric
 *   offset (e.g. "+02:00") instead of UTC ("Z").
 * @returns {string}
 *
 * @example
 * formatDate(new Date(Date.UTC(2024, 0, 15, 9, 30)))
 * // => "2024-01-15T09:30:00.000Z"
 * formatDate(new Date(Date.UTC(2024, 0, 15)), { dateOnly: true })
 * // => "2024-01-15"
 */
export function formatDate(date, { dateOnly = false, local = false } = {}) {
  const d = toDate(date);

  const year    = local ? d.getFullYear()     : d.getUTCFullYear();
  const month   = local ? d.getMonth() + 1    : d.getUTCMonth() + 1;
  const day     = local ? d.getDate()         : d.getUTCDate();
  const hours   = local ? d.getHours()        : d.getUTCHours();
  const minutes = local ? d.getMinutes()      : d.getUTCMinutes();
  const seconds = local ? d.getSeconds()      : d.getUTCSeconds();
  const millis  = local ? d.getMilliseconds() : d.getUTCMilliseconds();

  const datePart = `${formatYear(year)}-${pad(month, 2)}-${pad(day, 2)}`;
  if (dateOnly) return datePart;

  const timePart = `${pad(hours, 2)}:${pad(minutes, 2)}:${pad(seconds, 2)}.${pad(millis, 3)}`;

  let zone = 'Z';
  if (local) {
    const offset = -d.getTimezoneOffset(); // minutes east of UTC
    const sign = offset >= 0 ? '+' : '-';
    zone = `${sign}${pad(Math.floor(Math.abs(offset) / 60), 2)}:${pad(Math.abs(offset) % 60, 2)}`;
  }

  return `${datePart}T${timePart}${zone}`;
}

/**
 * Parse an ISO-8601 date or date-time string into a Date.
 *
 * Supported forms (extended format):
 *   YYYY-MM-DD
 *   YYYY-MM-DDTHH:mm
 *   YYYY-MM-DDTHH:mm:ss
 *   YYYY-MM-DDTHH:mm:ss.sss   (1–9 fractional digits; "," also accepted)
 *   ...followed optionally by Z, ±HH, ±HHmm, or ±HH:mm
 *   Expanded years: ±YYYYYY-MM-DD...
 *
 * Interpretation (matches ECMAScript conventions):
 *   - Date-only strings are treated as UTC midnight.
 *   - Date-time strings without an offset are treated as local time.
 *
 * @param {string} str
 * @returns {Date}
 * @throws {TypeError} If the input is not a string.
 * @throws {RangeError} If the string is not a valid ISO-8601 date.
 *
 * @example
 * parseDate('2024-01-15T09:30:00+02:00').toISOString()
 * // => "2024-01-15T07:30:00.000Z"
 */
export function parseDate(str) {
  if (typeof str !== 'string') {
    throw new TypeError(`parseDate: expected a string, got ${typeof str}`);
  }

  const input = str.trim();
  const match = ISO_REGEX.exec(input);
  if (!match) {
    throw new RangeError(`parseDate: invalid ISO-8601 date: "${str}"`);
  }

  const [, yearStr, monthStr, dayStr, hourStr, minuteStr, secondStr, fracStr, zoneStr] = match;

  if (yearStr === '-000000') {
    throw new RangeError(`parseDate: "-000000" is not a valid year: "${str}"`);
  }

  const year   = Number(yearStr);
  const month  = Number(monthStr);
  const day    = Number(dayStr);
  const hour   = hourStr   ? Number(hourStr)   : 0;
  const minute = minuteStr ? Number(minuteStr) : 0;
  const second = secondStr ? Number(secondStr) : 0;
  // Truncate fractional seconds to millisecond precision.
  const millis = fracStr ? Number(fracStr.slice(0, 3).padEnd(3, '0')) : 0;

  // Validate components.
  const fail = (what) => {
    throw new RangeError(`parseDate: ${what} out of range in "${str}"`);
  };
  if (month < 1 || month > 12) fail('month');
  if (day < 1 || day > daysInMonth(year, month)) fail('day');
  if (minute > 59) fail('minute');
  if (second > 59) fail('second'); // leap seconds can't be represented by Date
  if (hour > 24) fail('hour');
  if (hour === 24 && (minute !== 0 || second !== 0 || millis !== 0)) {
    fail('hour'); // "24:00" is only allowed as end-of-day midnight
  }

  // Parse timezone offset (in minutes east of UTC), or null for local time.
  let offsetMinutes = null;
  if (zoneStr) {
    if (zoneStr === 'Z' || zoneStr === 'z') {
      offsetMinutes = 0;
    } else {
      const sign = zoneStr[0] === '-' ? -1 : 1;
      const digits = zoneStr.slice(1).replace(':', '');
      const offH = Number(digits.slice(0, 2));
      const offM = digits.length > 2 ? Number(digits.slice(2, 4)) : 0;
      if (offH > 23 || offM > 59) fail('timezone offset');
      offsetMinutes = sign * (offH * 60 + offM);
    }
  }

  const isDateOnly = hourStr === undefined;
  const date = new Date(0);

  // Use setFullYear/setUTCFullYear rather than Date.UTC / the Date
  // constructor, which map years 0–99 to 1900–1999.
  if (isDateOnly || offsetMinutes !== null) {
    date.setUTCFullYear(year, month - 1, day);
    date.setUTCHours(hour, minute, second, millis);
    if (offsetMinutes) {
      date.setTime(date.getTime() - offsetMinutes * 60_000);
    }
  } else {
    date.setFullYear(year, month - 1, day);
    date.setHours(hour, minute, second, millis);
  }

  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`parseDate: date out of representable range: "${str}"`);
  }

  return date;
}

export default { formatDate, parseDate };
```

## Usage

```javascript
import { formatDate, parseDate } from './iso8601.js';

// Formatting
formatDate(new Date(Date.UTC(2024, 1, 29, 13, 5, 9, 42)));
// "2024-02-29T13:05:09.042Z"

formatDate(new Date(Date.UTC(2024, 1, 29)), { dateOnly: true });
// "2024-02-29"

formatDate(new Date(), { local: true });
// e.g. "2024-02-29T15:05:09.042+02:00"

// Parsing
parseDate('2024-02-29');                     // 2024-02-29T00:00:00.000Z
parseDate('2024-02-29T13:05:09.042Z');       // exact UTC instant
parseDate('2024-02-29T13:05+0530');          // offset without colon
parseDate('2024-02-29T24:00:00Z');           // → 2024-03-01T00:00:00.000Z
parseDate('+010000-01-01T00:00:00Z');        // expanded year

// Round trip
const d = new Date();
parseDate(formatDate(d)).getTime() === d.getTime(); // true

// Errors
parseDate('2023-02-29');   // RangeError: day out of range
parseDate('2024-13-01');   // RangeError: month out of range
parseDate('not a date');   // RangeError: invalid ISO-8601 date
```

## Notes

- **Strict validation:** Unlike `new Date(str)`, which is lenient and engine-dependent, `parseDate` rejects impossible dates like `2023-02-30` instead of silently rolling them over.
- **Years 0–99:** The code avoids the legacy `Date` behavior of mapping two-digit years to the 1900s.
- **Precision:** JavaScript `Date` has millisecond resolution, so extra fractional digits (e.g. nanoseconds) are truncated.
- **Not supported:** The basic format (`20240229T130509Z`), week dates (`2024-W09-4`), ordinal dates (`2024-060`), and durations/intervals. These can be added to the regex if you need them.

