 */
export function parseDate(str) {
  if (typeof str !== 'string') {
    throw new TypeError('parseDate expects a string');
  }

  const match = ISO_REGEX.exec(str.trim());
  if (!match) {
    throw new RangeError(`Invalid ISO-8601 date: "${str}"`);
  }

  const [, yStr, moStr, dStr, hStr, miStr, sStr, fracStr, offStr] = match;

