  const day = dStr ? parseInt(dStr, 10) : 1;
  const hour = hStr ? parseInt(hStr, 10) : 0;
  const minute = miStr ? parseInt(miStr, 10) : 0;
  const second = sStr ? parseInt(sStr, 10) : 0;
