  let offsetMinutes = null; // null => local time
  if (offsetStr !== undefined) {
    if (offsetStr.toUpperCase() === "Z") {
      offsetMinutes = 0;
    } else {
      const sign = offsetStr[0] === "-" ? -1 : 1;
      const digits = offsetStr.slice(1).replace(":", "");
      const offH = Number(digits.slice(0, 2));
      const offM = digits.length > 2 ? Number(digits.slice(2, 4)) : 0;
      if (offH > 23 || offM > 59) {
        throw new RangeError(`parseDate: offset out of range in "${str}"`);
