  // Use setFullYear/setUTCFullYear rather than the constructor / Date.UTC,
  // because those map years 0–99 to 1900–1999.
  const result = new Date(0);
  if (offsetMinutes === null) {
    result.setFullYear(year, month - 1, day);
    result.setHours(hour, minute, second, millisecond);
  } else {
    result.setUTCFullYear(year, month - 1, day);
    result.setUTCHours(hour, minute - offsetMinutes, second, millisecond);
  }

  if (Number.isNaN(result.getTime())) {
    throw new RangeError(`parseDate: date out of representable range in "${str}"`);
  }
  return result;
}

