  return new Date(Date.UTC(year, month, 0)).getUTCDate();
}

/**
 * Format a Date as an ISO-8601 calendar date (YYYY-MM-DD) using local time.
 * @param {Date} date
 * @returns {string}
 */
export function formatDate(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    throw new TypeError("formatDate: expected a valid Date");
  }
  const year = date.getFullYear();
  if (year < 0 || year > 9999) {
    throw new RangeError("formatDate: year must be between 0000 and 9999");
  }
  return `${pad(year, 4)}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

/**
 * Parse an ISO-8601 date or date-time string into a Date.
 * Rejects malformed input and out-of-range components (e.g. 2023-02-29).
 * @param {string} str
 * @returns {Date}
 */
export function parseDate(str) {
  if (typeof str !== "string") {
    throw new TypeError("parseDate: expected a string");
  }

  const m = ISO_RE.exec(str.trim());
  if (!m) {
    throw new RangeError(`parseDate: invalid ISO-8601 date: "${str}"`);
  }

  const [, y, mo, d, h = "0", mi = "0", s = "0", frac = "", tz] = m;
  const year = Number(y);
  const month = Number(mo);
  const day = Number(d);
  const hour = Number(h);
  const minute = Number(mi);
  const second = Number(s);
  // Convert fractional seconds to milliseconds (truncate beyond 3 digits).
  const ms = frac ? Number(frac.slice(0, 3).padEnd(3, "0")) : 0;

  if (
    month < 1 || month > 12 ||
    day < 1 || day > daysInMonth(year, month) ||
    hour > 23 || minute > 59 || second > 59
  ) {
    throw new RangeError(`parseDate: date out of range: "${str}"`);
  }

  let date;
  if (tz === undefined) {
    // No zone designator: local time.
    date = new Date(2000, 0, 1, hour, minute, second, ms);
    date.setFullYear(year, month - 1, day); // handles years 0-99 correctly
