 * Format a Date (or millisecond timestamp) as an ISO-8601 UTC string.
 *
 * @param {Date|number} date
 * @returns {string}
 */
export function formatDate(date) {
  let d;
  if (date instanceof Date) {
    d = date;
  } else if (typeof date === "number") {
    d = new Date(date);
  } else {
    throw new TypeError("formatDate: expected a Date or a timestamp number");
  }

  if (Number.isNaN(d.getTime())) {
    throw new RangeError("formatDate: invalid date");
  }

  // toISOString already produces the exact ISO-8601 extended format,
  // including ±YYYYYY for years outside 0000-9999.
  return d.toISOString();
}

