 * Supported input forms (extended or basic format):
 *
 *   YYYY
 *   YYYY-MM
 *   YYYY-MM-DD          YYYYMMDD
 *   ±YYYYYY-MM-DD       (expanded years)
 *
 * optionally followed by a time part, separated by "T" or a space:
 *
 *   HH:mm               HHmm
 *   HH:mm:ss            HHmmss
 *   HH:mm:ss.sss...     HHmmss.sss...   (fraction separator "." or ",")
 *
 * optionally followed by an offset:
 *
 *   Z | ±HH | ±HH:mm | ±HHmm
 */
const PATTERN = new RegExp(
  "^" +
    "(?<year>[+-]\\d{6}|\\d{4})" +
    "(?:" +
      "(?<dsep>-?)(?<month>\\d{2})" +
      "(?:\\k<dsep>(?<day>\\d{2}))?" +
    ")?" +
    "(?:[T ]" +
