/**
 * Parse an ISO-8601 date/time string into a Date.
 *
 * @param {string} str
 * @returns {Date}
 */
export function parseDate(str) {
  if (typeof str !== "string") {
    throw new TypeError("parseDate: expected a string");
  }

  const input = str.trim();
  const match = PATTERN.exec(input);
  if (!match) {
    throw new RangeError(`parseDate: not a valid ISO-8601 date: "${str}"`);
  }

  const g = match.groups;

  // "-000000" is explicitly disallowed by ISO-8601 / ECMAScript.
  if (g.year === "-000000") {
    throw new RangeError(`parseDate: invalid year in "${str}"`);
  }

