    addDay = true;
  } else if (hour > 23) {
    throw new RangeError(`parseDate: hour out of range in "${str}"`);
  }

  // --- Offset -------------------------------------------------------------
  let offsetMinutes = 0;
  if (g.offset !== undefined && g.offset.toUpperCase() !== "Z") {
    const sign = g.offset[0] === "-" ? -1 : 1;
    const digits = g.offset.slice(1).replace(":", "");
    const offH = parseInt(digits.slice(0, 2), 10);
    const offM = digits.length > 2 ? parseInt(digits.slice(2, 4), 10) : 0;
    if (offH > 23 || offM > 59) {
      throw new RangeError(`parseDate: offset out of range in "${str}"`);
    }
    offsetMinutes = sign * (offH * 60 + offM);
  }

  // --- Build the Date ------------------------------------------------------
  // Use setUTCFullYear so years 0-99 aren't mapped to 1900-1999.
  const d = new Date(0);
  d.setUTCFullYear(year, month - 1, day + (addDay ? 1 : 0));
  d.setUTCHours(hour, minute, second, millis);

  const time = d.getTime() - offsetMinutes * MS_PER_MINUTE;
  const result = new Date(time);

  if (Number.isNaN(result.getTime())) {
    // Outside Date's representable range (±8.64e15 ms).
    throw new RangeError(`parseDate: date out of representable range: "${str}"`);
  }

  return result;
}
