// "2024-03-15T13:45:30.123Z"

parseDate("2024-03-15");                    // 2024-03-15T00:00:00.000Z
parseDate("2024-03-15T13:45:30+02:00");     // 2024-03-15T11:45:30.000Z
parseDate("20240315T134530Z");              // basic format works too
parseDate("2024-12-31T24:00:00Z");          // 2025-01-01T00:00:00.000Z

