## Design notes

- **Strings without an offset are treated as UTC.** Native `Date` parsing treats date-only strings as UTC but date-time strings as local time. That inconsistency is a common source of bugs, so this module always uses UTC. If you need local time, append the offset explicitly.
- **Validation is strict.** Inputs like `2023-02-30` or `13:60` throw an error. Native `Date` would either silently roll them over or return `Invalid Date`.
- **Precision is milliseconds.** Extra fractional-second digits are truncated, because `Date` cannot represent anything finer.
- **Leap seconds (`:60`) are rejected**, since `Date` cannot represent them.
- **ISO week dates (`2024-W11-5`) and ordinal dates (`2024-075`) are not supported.**

# dateUtils.js

```javascript
/**
 * ISO-8601 date utilities.
 *
 * formatDate(date) -> "YYYY-MM-DDTHH:mm:ss.sssZ" (always UTC)
 * parseDate(str)   -> Date (throws on invalid input)
 *
 * Supported input formats for parseDate:
 *   YYYY-MM-DD
 *   YYYY-MM-DDTHH:mm
 *   YYYY-MM-DDTHH:mm:ss
 *   YYYY-MM-DDTHH:mm:ss.sss   (1-9 fractional digits; extra precision truncated to ms)
 *   ...each time form optionally followed by "Z", "±HH:mm", "±HHmm", or "±HH"
 *   A space is accepted in place of "T".
 *
 * Interpretation rules:
 *   - Date-only strings are treated as UTC midnight.
 *   - Date-time strings with no offset are treated as local time.
 *   These rules match the ECMAScript spec for Date.parse.
 */

const ISO_REGEX = new RegExp(
  '^' +
    '(\\d{4})-(\\d{2})-(\\d{2})' +              // date: YYYY-MM-DD
    '(?:[T ]' +
      '(\\d{2}):(\\d{2})' +                     // time: HH:mm
      '(?::(\\d{2})(?:[.,](\\d{1,9}))?)?' +     // optional :ss and .fraction
      '(Z|[+-]\\d{2}(?::?\\d{2})?)?' +          // optional offset
    ')?' +
  '$',
  'i'
);

function pad(num, width = 2) {
  return String(num).padStart(width, '0');
}

function isLeapYear(y) {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y, m) {
  return [31, isLeapYear(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];
}

/**
 * Format a Date (or timestamp) as an ISO-8601 UTC string.
 * @param {Date|number} date
 * @returns {string}
 */
export function formatDate(date) {
  const d = date instanceof Date ? date : new Date(date);
  if (Number.isNaN(d.getTime())) {
    throw new RangeError('formatDate: invalid date');
  }

  const year = d.getUTCFullYear();
  if (year < 0 || year > 9999) {
    // ISO-8601 expanded year format: ±YYYYYY
    const sign = year < 0 ? '-' : '+';
    return `${sign}${pad(Math.abs(year), 6)}` + d.toISOString().slice(d.toISOString().indexOf('-', 1));
  }

  return (
    `${pad(year, 4)}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}` +
    `T${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}` +
    `.${pad(d.getUTCMilliseconds(), 3)}Z`
  );
}

/**
 * Parse an ISO-8601 date string into a Date.
 * @param {string} str
 * @returns {Date}
 * @throws {TypeError|RangeError} on invalid input
 */
export function parseDate(str) {
  if (typeof str !== 'string') {
    throw new TypeError('parseDate: expected a string');
  }

  const match = ISO_REGEX.exec(str.trim());
  if (!match) {
    throw new RangeError(`parseDate: invalid ISO-8601 string "${str}"`);
  }

  const [, ys, mos, ds, hs, mis, ss, frac, offset] = match;
  const year = Number(ys);
  const month = Number(mos);
  const day = Number(ds);
  const hasTime = hs !== undefined;
  const hour = hasTime ? Number(hs) : 0;
  const minute = hasTime ? Number(mis) : 0;
  const second = ss !== undefined ? Number(ss) : 0;
  const ms = frac !== undefined ? Number(frac.padEnd(3, '0').slice(0, 3)) : 0;

  // Range validation
  if (month < 1 || month > 12) throw new RangeError(`parseDate: invalid month in "${str}"`);
  if (day < 1 || day > daysInMonth(year, month)) throw new RangeError(`parseDate: invalid day in "${str}"`);
  // Allow 24:00:00.000 as end-of-day per ISO-8601
  const isEndOfDay = hour === 24 && minute === 0 && second === 0 && ms === 0;
  if ((hour > 23 && !isEndOfDay) || minute > 59 || second > 59) {
    throw new RangeError(`parseDate: invalid time in "${str}"`);
  }

  let time;

  if (!hasTime || offset) {
    // UTC-based computation
    time = Date.UTC(year, month - 1, day, hour, minute, second, ms);
    // Date.UTC maps years 0-99 to 1900-1999; correct that
    if (year < 100) {
      const tmp = new Date(time);
      tmp.setUTCFullYear(year);
      time = tmp.getTime();
    }

    if (offset && offset.toUpperCase() !== 'Z') {
      const sign = offset[0] === '-' ? -1 : 1;
      const digits = offset.slice(1).replace(':', '');
      const offH = Number(digits.slice(0, 2));
      const offM = digits.length > 2 ? Number(digits.slice(2, 4)) : 0;
      if (offH > 23 || offM > 59) {
        throw new RangeError(`parseDate: invalid offset in "${str}"`);
      }
      time -= sign * (offH * 60 + offM) * 60 * 1000;
    }
  } else {
    // No offset with a time component -> local time
    const local = new Date(year, month - 1, day, hour, minute, second, ms);
    if (year < 100) local.setFullYear(year);
    time = local.getTime();
  }

  const result = new Date(time);
  if (Number.isNaN(result.getTime())) {
    throw new RangeError(`parseDate: date out of range "${str}"`);
  }
  return result;
}

export default { formatDate, parseDate };
