## Usage

```javascript
import { formatDate, parseDate } from "./isoDate.js";

const d = parseDate("2024-03-15T13:45:30.123+05:30");
formatDate(d);                          // "2024-03-15T08:15:30.123Z"
formatDate(d, { milliseconds: false }); // "2024-03-15T08:15:30Z"
formatDate(d, { dateOnly: true });      // "2024-03-15"
formatDate(d, { utc: false });          // e.g. "2024-03-15T04:15:30.123-04:00"

parseDate("20240315T134530Z");          // Basic format
parseDate("2024-02-29");                // Leap day, UTC midnight
parseDate("+012345-01-01");             // Expanded year
parseDate("2024-03-15T24:00");          // Local midnight on 2024-03-16

parseDate("2023-02-29");                // RangeError: day out of range
parseDate("2024-13-01");                // RangeError: month out of range
parseDate("March 15, 2024");            // RangeError: invalid ISO-8601 string
```

## Design Notes

- **Strict validation.** `new Date("2023-02-31")` silently rolls over to March 3. `parseDate` rejects impossible dates instead.
- **Small years.** The parser uses `setUTCFullYear` and `setFullYear` so that a year like `0050` stays year 50. The `Date` constructor would turn it into 1950.
- **Fractional seconds** beyond millisecond precision are truncated, because JS `Date` cannot store them.
- **Leap seconds** (`:60`) are rejected, because JS `Date` cannot represent them.
- **CommonJS:** to use this with `require`, replace the export lines with `module.exports = { formatDate, parseDate };`.

# ISO-8601 Date Utilities

```javascript
// iso-date.js
// Utilities for formatting and parsing ISO-8601 dates.

/**
 * Matches the ISO-8601 extended format:
 *   YYYY-MM-DD
 *   YYYY-MM-DDTHH:mm
 *   YYYY-MM-DDTHH:mm:ss
 *   YYYY-MM-DDTHH:mm:ss.sss (any number of fraction digits; "," also allowed)
 * followed by an optional offset: Z, ±HH, ±HHmm, or ±HH:mm.
 * Expanded years (±YYYYYY) are supported.
 */
const ISO_RE =
  /^([+-]\d{6}|\d{4})-(\d{2})-(\d{2})(?:[Tt](\d{2}):(\d{2})(?::(\d{2})(?:[.,](\d+))?)?([Zz]|[+-]\d{2}(?::?\d{2})?)?)?$/;

function isLeapYear(y) {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y, m) {
  return [31, isLeapYear(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];
}

/**
 * Formats a Date as an ISO-8601 string in UTC.
 *
 * @param {Date} date
 * @returns {string} e.g. "2024-03-15T13:45:30.123Z"
 * @throws {TypeError} if the argument is not a valid Date
 */
export function formatDate(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    throw new TypeError("formatDate: expected a valid Date object");
  }
  return date.toISOString();
}

/**
 * Parses an ISO-8601 date or date-time string into a Date.
 *
 * Behavior matches the ECMAScript spec for ambiguous cases:
 *   - Date-only strings ("2024-03-15") are interpreted as UTC midnight.
 *   - Date-time strings without an offset are interpreted as local time.
 *   - "24:00" (or "24:00:00") is accepted as midnight at the end of the day.
 *
 * @param {string} str
 * @returns {Date}
 * @throws {TypeError} if the argument is not a string
 * @throws {RangeError} if the string is not a valid ISO-8601 date
 */
export function parseDate(str) {
  if (typeof str !== "string") {
    throw new TypeError("parseDate: expected a string");
  }

  const match = ISO_RE.exec(str.trim());
  if (!match) {
    throw new RangeError(`parseDate: invalid ISO-8601 date "${str}"`);
  }

  const [, yearStr, monStr, dayStr, hourStr, minStr, secStr, fracStr, offsetStr] = match;

  if (yearStr === "-000000") {
    throw new RangeError(`parseDate: "-000000" is not a valid year`);
  }

  const year = Number(yearStr);
  const month = Number(monStr);
  const day = Number(dayStr);
  const hour = hourStr ? Number(hourStr) : 0;
  const minute = minStr ? Number(minStr) : 0;
  const second = secStr ? Number(secStr) : 0;
  // Normalize the fraction to milliseconds (truncate extra precision).
  const ms = fracStr ? Number(fracStr.slice(0, 3).padEnd(3, "0")) : 0;

  // Validate components.
  if (month < 1 || month > 12) {
    throw new RangeError(`parseDate: month out of range in "${str}"`);
  }
  if (day < 1 || day > daysInMonth(year, month)) {
    throw new RangeError(`parseDate: day out of range in "${str}"`);
  }
  const isEndOfDay = hour === 24 && minute === 0 && second === 0 && ms === 0;
  if ((hour > 23 && !isEndOfDay) || minute > 59 || second > 59) {
    throw new RangeError(`parseDate: time out of range in "${str}"`);
  }

  // Compute the offset in minutes (null means "no offset given").
  let offsetMinutes = null;
  if (offsetStr) {
    if (offsetStr === "Z" || offsetStr === "z") {
      offsetMinutes = 0;
    } else {
      const sign = offsetStr[0] === "-" ? -1 : 1;
      const digits = offsetStr.slice(1).replace(":", "");
      const offH = Number(digits.slice(0, 2));
      const offM = digits.length > 2 ? Number(digits.slice(2, 4)) : 0;
      if (offH > 23 || offM > 59) {
        throw new RangeError(`parseDate: offset out of range in "${str}"`);
      }
      offsetMinutes = sign * (offH * 60 + offM);
    }
  }

  // Build the Date. setUTCFullYear/setFullYear are used instead of the
  // Date constructor to avoid the legacy mapping of years 0–99 to 1900–1999.
  const date = new Date(0);
  const useUTC = !hourStr || offsetMinutes !== null;

  if (useUTC) {
    date.setUTCFullYear(year, month - 1, day);
    date.setUTCHours(hour, minute, second, ms);
    if (offsetMinutes) {
      date.setTime(date.getTime() - offsetMinutes * 60_000);
    }
  } else {
    date.setFullYear(year, month - 1, day);
    date.setHours(hour, minute, second, ms);
  }

  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`parseDate: date out of representable range in "${str}"`);
  }
  return date;
}
