```javascript
import { formatDate, parseDate } from "./iso-date.js";

formatDate(new Date(Date.UTC(2024, 2, 15, 13, 45, 30, 123)));
// "2024-03-15T13:45:30.123Z"

parseDate("2024-03-15");                 // 2024-03-15T00:00:00.000Z (UTC)
parseDate("2024-03-15T13:45:30Z");       // 2024-03-15T13:45:30.000Z
parseDate("2024-03-15T13:45:30+02:00");  // 2024-03-15T11:45:30.000Z
parseDate("2024-03-15T13:45:30.123456Z");// fraction truncated to .123
parseDate("2024-03-15T24:00");           // midnight, start of 2024-03-16 (local)
parseDate("+010000-01-01T00:00:00Z");    // expanded year 10000

parseDate("2023-02-29");   // RangeError: day out of range
parseDate("2024-13-01");   // RangeError: month out of range
parseDate("03/15/2024");   // RangeError: invalid ISO-8601 date
