## Notes

- **Strict validation:** Unlike `new Date(str)`, which silently accepts many non-ISO formats and rolls over invalid values (e.g. Feb 30 becomes Mar 2), `parseDate` rejects anything that isn't a well-formed, real calendar date.
- **Round-tripping:** `parseDate(formatDate(d)).getTime() === d.getTime()` holds for any valid Date.
- **Years 0–99:** These are handled correctly as literal years (e.g. `"0050-01-01"` is year 50, not 1950).
- **Leap seconds:** `:60` is rejected because JavaScript `Date` cannot represent leap seconds.

# ISO-8601 Date Utilities

```javascript
// iso8601.js
//
// Utilities for formatting and parsing ISO-8601 dates.
//
//   formatDate(date, options?) -> string
//   parseDate(str)             -> Date
//
// Supported input formats for parseDate (extended format):
//   YYYY-MM-DD                         (interpreted as UTC midnight)
//   YYYY-MM-DDTHH:mm
//   YYYY-MM-DDTHH:mm:ss
//   YYYY-MM-DDTHH:mm:ss.sss            (any number of fractional digits)
//   ...followed by optional offset:  Z | ±HH | ±HHMM | ±HH:MM
//
// A date-time without an offset is interpreted as local time (per ISO-8601
// and consistent with the ECMAScript Date spec). A space may be used
// instead of "T", and a comma instead of "." for fractional seconds.

const ISO_REGEX =
  /^(\d{4})-(\d{2})-(\d{2})(?:[Tt ](\d{2}):(\d{2})(?::(\d{2})(?:[.,](\d+))?)?(Z|z|[+-]\d{2}(?::?\d{2})?)?)?$/;

function pad(num, length = 2) {
  return String(Math.abs(num)).padStart(length, "0");
}

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year, month) {
  // month is 1-12
  return [31, isLeapYear(year) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
}

function formatYear(year) {
  // ISO-8601 requires a sign and at least 6 digits for years outside 0000-9999.
  if (year >= 0 && year <= 9999) return pad(year, 4);
  return (year < 0 ? "-" : "+") + pad(year, 6);
}

/**
 * Format a Date as an ISO-8601 string.
 *
 * @param {Date|number|string} date - A Date, timestamp, or anything `new Date()` accepts.
 * @param {Object} [options]
 * @param {boolean} [options.dateOnly=false]   - Output only "YYYY-MM-DD".
 * @param {boolean} [options.local=false]      - Use local time with a numeric offset
 *                                               instead of UTC with "Z".
 * @param {boolean} [options.milliseconds=true] - Include ".sss" in the output.
 * @returns {string}
 * @throws {TypeError} If the date is invalid.
 */
export function formatDate(date, options = {}) {
  const { dateOnly = false, local = false, milliseconds = true } = options;

  const d = date instanceof Date ? date : new Date(date);
  if (Number.isNaN(d.getTime())) {
    throw new TypeError(`formatDate: invalid date: ${String(date)}`);
  }

  const get = local
    ? {
        year: d.getFullYear(), month: d.getMonth() + 1, day: d.getDate(),
        hours: d.getHours(), minutes: d.getMinutes(),
        seconds: d.getSeconds(), ms: d.getMilliseconds(),
      }
    : {
        year: d.getUTCFullYear(), month: d.getUTCMonth() + 1, day: d.getUTCDate(),
        hours: d.getUTCHours(), minutes: d.getUTCMinutes(),
        seconds: d.getUTCSeconds(), ms: d.getUTCMilliseconds(),
      };

  const datePart = `${formatYear(get.year)}-${pad(get.month)}-${pad(get.day)}`;
  if (dateOnly) return datePart;

  let timePart = `${pad(get.hours)}:${pad(get.minutes)}:${pad(get.seconds)}`;
  if (milliseconds) timePart += `.${pad(get.ms, 3)}`;

  let offset = "Z";
  if (local) {
    const offsetMinutes = -d.getTimezoneOffset(); // positive east of UTC
    const sign = offsetMinutes >= 0 ? "+" : "-";
    const abs = Math.abs(offsetMinutes);
    offset = `${sign}${pad(Math.floor(abs / 60))}:${pad(abs % 60)}`;
  }

  return `${datePart}T${timePart}${offset}`;
}

/**
 * Parse an ISO-8601 date or date-time string into a Date.
 * Performs strict validation (e.g. rejects "2023-02-30" or "25:00").
 *
 * @param {string} str
 * @returns {Date}
 * @throws {TypeError} If the input is not a string.
 * @throws {RangeError} If the string is not a valid ISO-8601 date.
 */
export function parseDate(str) {
  if (typeof str !== "string") {
    throw new TypeError(`parseDate: expected a string, got ${typeof str}`);
  }

  const match = ISO_REGEX.exec(str.trim());
  if (!match) {
    throw new RangeError(`parseDate: invalid ISO-8601 string: "${str}"`);
  }

  const [, y, mo, da, h, mi, s, frac, tz] = match;

  const year = Number(y);
  const month = Number(mo);
  const day = Number(da);
  const hours = h !== undefined ? Number(h) : 0;
  const minutes = mi !== undefined ? Number(mi) : 0;
  const seconds = s !== undefined ? Number(s) : 0;
  // Use the first 3 fractional digits as milliseconds (truncating extra precision).
  const ms = frac !== undefined ? Number(frac.slice(0, 3).padEnd(3, "0")) : 0;

  const fail = (reason) => {
    throw new RangeError(`parseDate: ${reason} in "${str}"`);
  };

  // --- Component validation ---
  if (month < 1 || month > 12) fail("month out of range");
  if (day < 1 || day > daysInMonth(year, month)) fail("day out of range");

  // ISO-8601 permits 24:00:00 to denote end of day.
  const isEndOfDay = hours === 24;
  if (isEndOfDay) {
    if (minutes !== 0 || seconds !== 0 || ms !== 0) fail("hour 24 must be 24:00:00");
  } else if (hours > 23) {
    fail("hour out of range");
  }
  if (minutes > 59) fail("minute out of range");
  if (seconds > 59) fail("second out of range"); // leap seconds not supported by Date

  // --- Offset handling ---
  let offsetMinutes = null; // null => local time
  if (tz !== undefined) {
    if (tz === "Z" || tz === "z") {
      offsetMinutes = 0;
    } else {
      const sign = tz[0] === "-" ? -1 : 1;
      const digits = tz.slice(1).replace(":", "");
      const offH = Number(digits.slice(0, 2));
      const offM = digits.length > 2 ? Number(digits.slice(2, 4)) : 0;
      if (offH > 23 || offM > 59) fail("timezone offset out of range");
      offsetMinutes = sign * (offH * 60 + offM);
    }
  } else if (h === undefined) {
    // Date-only forms are treated as UTC (matches ECMAScript behaviour).
    offsetMinutes = 0;
  }

  // --- Construct the Date ---
  // setFullYear/setUTCFullYear are used because the Date constructor and
  // Date.UTC map years 0-99 to 1900-1999.
  let result;
  if (offsetMinutes === null) {
    result = new Date(2000, 0, 1, 0, 0, 0, 0);
    result.setFullYear(year, month - 1, day);
    result.setHours(hours, minutes, seconds, ms);
  } else {
    result = new Date(Date.UTC(2000, 0, 1));
    result.setUTCFullYear(year, month - 1, day);
    result.setUTCHours(hours, minutes, seconds, ms);
    result = new Date(result.getTime() - offsetMinutes * 60_000);
  }

  if (Number.isNaN(result.getTime())) fail("date out of representable range");
  return result;
}

export default { formatDate, parseDate };
```

## Usage

```javascript
import { formatDate, parseDate } from "./iso8601.js";

formatDate(new Date(Date.UTC(2024, 1, 29, 13, 5, 9, 42)));
// "2024-02-29T13:05:09.042Z"

formatDate(new Date(), { dateOnly: true });        // "2024-06-01"
formatDate(new Date(), { local: true });           // "2024-06-01T15:30:00.000+02:00"
formatDate(new Date(), { milliseconds: false });   // "2024-06-01T13:30:00Z"

parseDate("2024-02-29");                    // 2024-02-29T00:00:00.000Z
parseDate("2024-02-29T13:05:09.042Z");      // 2024-02-29T13:05:09.042Z
parseDate("2024-02-29T15:05:09+02:00");     // 2024-02-29T13:05:09.000Z
parseDate("2024-02-29T13:05");              // local time
parseDate("2024-12-31T24:00:00Z");          // 2025-01-01T00:00:00.000Z

parseDate("2023-02-29");   // RangeError: day out of range
parseDate("2024-13-01");   // RangeError: month out of range
parseDate("not a date");   // RangeError: invalid ISO-8601 string

// Round-trip
const d = new Date();
parseDate(formatDate(d)).getTime() === d.getTime(); // true
```

## Design Notes

- **Strict validation:** The native `Date` constructor silently rolls over invalid values, so `new Date("2023-02-30")` may become March 2. `parseDate` rejects these instead.
- **Timezone rules:**
  - Date-only strings are parsed as UTC.
  - Date-time strings without an offset are parsed as local time.
  - Both rules match the ECMAScript specification, so behavior stays consistent with `Date`.
- **Years 0–99:** The code uses `setUTCFullYear` because `Date.UTC(99, …)` would otherwise produce the year 1999.
- **Extended years:** `formatDate` emits `+YYYYYY` or `-YYYYYY` for years outside 0000–9999, as ISO-8601 requires.
- **Not supported:**
  - Basic format without separators, such as `20240229T130509Z`.
  - Week dates, such as `2024-W09-4`.
  - Ordinal dates, such as `2024-060`.
  - Leap seconds (`:60`).

  These are rare in practice, and the regex can be extended to cover them if needed.

# ISO-8601 Date Utilities

```javascript
// isoDate.js
// Utilities for formatting and parsing ISO-8601 dates.

/**
 * Pads a number with leading zeros to the given width.
 * @param {number} n
 * @param {number} width
 * @returns {string}
 */
function pad(n, width = 2) {
  return String(Math.abs(n)).padStart(width, '0');
}

/**
 * Formats a year per ISO-8601. Years 0–9999 use 4 digits. Years outside
 * that range use the expanded form (sign + 6 digits), matching
 * Date.prototype.toISOString.
 * @param {number} year
 * @returns {string}
 */
function formatYear(year) {
  if (year >= 0 && year <= 9999) return pad(year, 4);
  return (year < 0 ? '-' : '+') + pad(year, 6);
}

/**
 * Formats a Date as an ISO-8601 string.
 *
 * @param {Date} date - The date to format.
 * @param {Object} [options]
 * @param {boolean} [options.dateOnly=false] - Output only "YYYY-MM-DD".
 * @param {boolean} [options.utc=true] - If true, output in UTC with a "Z"
 *   suffix. If false, output local time with a numeric offset (e.g. "+02:00").
 * @returns {string}
 *
 * @example
 * formatDate(new Date(Date.UTC(2024, 0, 15, 10, 30)));
 * // "2024-01-15T10:30:00.000Z"
 * formatDate(new Date(Date.UTC(2024, 0, 15)), { dateOnly: true });
 * // "2024-01-15"
 */
export function formatDate(date, { dateOnly = false, utc = true } = {}) {
  if (!(date instanceof Date)) {
    throw new TypeError('formatDate: expected a Date instance');
  }
  if (Number.isNaN(date.getTime())) {
    throw new RangeError('formatDate: invalid Date');
  }

  const parts = utc
    ? {
        y: date.getUTCFullYear(),
        mo: date.getUTCMonth() + 1,
        d: date.getUTCDate(),
        h: date.getUTCHours(),
        mi: date.getUTCMinutes(),
        s: date.getUTCSeconds(),
        ms: date.getUTCMilliseconds(),
      }
    : {
        y: date.getFullYear(),
        mo: date.getMonth() + 1,
        d: date.getDate(),
        h: date.getHours(),
        mi: date.getMinutes(),
        s: date.getSeconds(),
        ms: date.getMilliseconds(),
      };

  const datePart = `${formatYear(parts.y)}-${pad(parts.mo)}-${pad(parts.d)}`;
  if (dateOnly) return datePart;

  const timePart = `${pad(parts.h)}:${pad(parts.mi)}:${pad(parts.s)}.${pad(parts.ms, 3)}`;

  let offset;
  if (utc) {
    offset = 'Z';
  } else {
    // getTimezoneOffset() returns minutes *behind* UTC, so invert the sign.
    const totalMinutes = -date.getTimezoneOffset();
    const sign = totalMinutes >= 0 ? '+' : '-';
    const abs = Math.abs(totalMinutes);
    offset = `${sign}${pad(Math.floor(abs / 60))}:${pad(abs % 60)}`;
  }

  return `${datePart}T${timePart}${offset}`;
}

// Strict ISO-8601 pattern (extended format):
//   YYYY-MM-DD
//   YYYY-MM-DDTHH:mm
//   YYYY-MM-DDTHH:mm:ss
//   YYYY-MM-DDTHH:mm:ss.sss (any number of fractional digits)
// followed by an optional zone: Z, ±HH, ±HH:mm, or ±HHmm.
// Expanded years (±YYYYYY) are also accepted.
const ISO_REGEX = new RegExp(
  '^' +
    '([+-]\\d{6}|\\d{4})' +            // 1: year
    '-(\\d{2})' +                      // 2: month
    '-(\\d{2})' +                      // 3: day
    '(?:' +
      '[Tt ]' +
      '(\\d{2})' +                     // 4: hour
      ':(\\d{2})' +                    // 5: minute
      '(?::(\\d{2})' +                 // 6: second
        '(?:[.,](\\d+))?' +            // 7: fraction
      ')?' +
      '(' +                            // 8: zone
        '[Zz]|[+-]\\d{2}(?::?\\d{2})?' +
      ')?' +
    ')?' +
  '$'
);

function isLeapYear(y) {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y, m) {
  return [31, isLeapYear(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];
}

/**
 * Parses an ISO-8601 date/time string into a Date.
 *
 * Behavior:
 *  - Date-only strings ("2024-01-15") are interpreted as UTC midnight,
 *    consistent with the built-in Date parser.
 *  - Date-time strings with a zone ("Z" or "±HH:mm") are interpreted
 *    in that zone.
 *  - Date-time strings without a zone are interpreted as local time.
 *  - Fractional seconds beyond milliseconds are truncated.
 *
 * Validation is strict: out-of-range components (e.g. "2023-02-29",
 * "25:00") throw a RangeError rather than silently rolling over.
 *
 * @param {string} str
 * @returns {Date}
 *
 * @example
 * parseDate('2024-01-15T10:30:00Z');      // 2024-01-15T10:30:00.000Z
 * parseDate('2024-01-15T12:30:00+02:00'); // 2024-01-15T10:30:00.000Z
 * parseDate('2024-01-15');                // 2024-01-15T00:00:00.000Z
 */
export function parseDate(str) {
  if (typeof str !== 'string') {
    throw new TypeError('parseDate: expected a string');
  }

  const match = ISO_REGEX.exec(str.trim());
  if (!match) {
    throw new RangeError(`parseDate: invalid ISO-8601 string: "${str}"`);
  }

  const [, yStr, moStr, dStr, hStr, miStr, sStr, fracStr, zone] = match;

  if (yStr === '-000000') {
    throw new RangeError('parseDate: "-000000" is not a valid year');
  }

  const year = Number(yStr);
  const month = Number(moStr);
  const day = Number(dStr);
  const hour = hStr !== undefined ? Number(hStr) : 0;
  const minute = miStr !== undefined ? Number(miStr) : 0;
  const second = sStr !== undefined ? Number(sStr) : 0;
  const ms = fracStr !== undefined ? Number(fracStr.slice(0, 3).padEnd(3, '0')) : 0;

  if (month < 1 || month > 12) {
    throw new RangeError(`parseDate: month out of range in "${str}"`);
  }
  if (day < 1 || day > daysInMonth(year, month)) {
    throw new RangeError(`parseDate: day out of range in "${str}"`);
  }
  if (hour > 23 || minute > 59 || second > 59) {
    throw new RangeError(`parseDate: time out of range in "${str}"`);
  }

  const hasTime = hStr !== undefined;

  // Use setUTCFullYear so that years 0–99 aren't mapped to 1900–1999
  // (a quirk of Date.UTC and the Date constructor).
  const date = new Date(0);

  if (!hasTime || zone !== undefined) {
    // Date-only (UTC) or explicit zone: compute in UTC, then apply offset.
    date.setUTCFullYear(year, month - 1, day);
    date.setUTCHours(hour, minute, second, ms);

    if (zone && zone.toUpperCase() !== 'Z') {
      const sign = zone[0] === '-' ? -1 : 1;
      const digits = zone.slice(1).replace(':', '');
      const offH = Number(digits.slice(0, 2));
      const offM = digits.length > 2 ? Number(digits.slice(2, 4)) : 0;
      if (offH > 23 || offM > 59) {
        throw new RangeError(`parseDate: zone offset out of range in "${str}"`);
      }
      // Local time = UTC + offset, so UTC = local - offset.
      date.setTime(date.getTime() - sign * (offH * 60 + offM) * 60_000);
    }
  } else {
    // Date-time without zone: local time.
    date.setFullYear(year, month - 1, day);
    date.setHours(hour, minute, second, ms);
  }

  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`parseDate: date out of representable range: "${str}"`);
  }

  return date;
}
```

## Usage

```javascript
import { formatDate, parseDate } from './isoDate.js';

const d = parseDate('2024-03-10T14:45:30.123+05:30');
console.log(formatDate(d));                      // "2024-03-10T09:15:30.123Z"
console.log(formatDate(d, { dateOnly: true }));  // "2024-03-10"
console.log(formatDate(d, { utc: false }));      // e.g. "2024-03-10T10:15:30.123+01:00"

// Round-trip
const original = new Date();
console.log(parseDate(formatDate(original)).getTime() === original.getTime()); // true

// Strict validation
parseDate('2023-02-29');  // RangeError: day out of range
parseDate('2024-13-01');  // RangeError: month out of range
parseDate('not a date');  // RangeError: invalid ISO-8601 string
```

## Design Notes

- **Strict parsing:** The built-in `new Date(str)` silently rolls over invalid values. For example, `"2023-02-31"` becomes March 3. `parseDate` rejects these values instead.
- **Date-only strings are treated as UTC**, which matches how JavaScript's native parser handles them. Date-time strings without an offset are treated as **local time**, as ISO-8601 specifies.
- **Years 0–99 are handled correctly.** The code uses `setUTCFullYear`/`setFullYear` because `Date.UTC(50, ...)` would otherwise become 1950.
- **Accepted zone formats:** `Z`, `±HH`, `±HHmm`, and `±HH:mm`. Both `.` and `,` are accepted as fractional-second separators.
- **Not supported:** week dates (`2024-W10-1`), ordinal dates (`2024-070`), basic format without separators (`20240310`), and `24:00`. You can add these if needed.

```javascript
// mathUtils.js

/**
 * Restrict a number to the range [min, max].
 * If min > max, the bounds are swapped.
 * @param {number} value
 * @param {number} min
 * @param {number} max
 * @returns {number}
 */
export function clamp(value, min, max) {
  if (min > max) [min, max] = [max, min];
  return Math.min(Math.max(value, min), max);
}

/**
 * Linearly interpolate between a and b.
 * t = 0 returns a, t = 1 returns b. Values outside [0, 1] extrapolate.
 * @param {number} a
 * @param {number} b
 * @param {number} t
 * @returns {number}
 */
export function lerp(a, b, t) {
  return a + (b - a) * t;
}

/**
 * Return a random integer in the inclusive range [min, max].
 * Non-integer bounds are narrowed to the integers inside the range.
 * @param {number} min
 * @param {number} max
 * @returns {number}
 */
export function randomInt(min, max) {
  let lo = Math.ceil(Math.min(min, max));
  let hi = Math.floor(Math.max(min, max));
  if (lo > hi) throw new RangeError("No integer exists in the given range");
  return Math.floor(Math.random() * (hi - lo + 1)) + lo;
}
