  if (min > max) [min, max] = [max, min];
  const lo = Math.ceil(min);
  const hi = Math.floor(max);
  if (lo > hi) {
    throw new RangeError("randomInt: no integer exists in the given range");
  }
  return Math.floor(Math.random() * (hi - lo + 1)) + lo;
