function parseDate(str) {
  if (typeof str !== "string") {
    throw new TypeError("parseDate expects a string");
  }

  const m = ISO_REGEX.exec(str.trim());
  if (!m) {
    throw new RangeError(`Invalid ISO-8601 date: "${str}"`);
  }

  const year = +m[1];
  const month = +m[2];
  const day = +m[3];
  const hasTime = m[4] !== undefined;
  const hour = hasTime ? +m[4] : 0;
