  const millis = (fraction ?? "").padEnd(3, "0").slice(0, 3);
  const timestamp = hour === undefined
    ? `${str}T00:00:00.000Z`
    : `${yearText}-${monthText}-${dayText}T${hour}:${minute}:${second}.${millis}${zone}`;
