// ISO-8601 calendar dates in YYYY-MM-DD format, interpreted as UTC.

export function formatDate(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    throw new TypeError("formatDate expects a valid Date");
  }

  const iso = date.toISOString();

  // Extended years outside 0000–9999 produce a longer ISO string.
  if (iso.length !== 24) {
    throw new RangeError("Only years 0000 through 9999 are supported");
  }

  return iso.slice(0, 10);
}

export function parseDate(str) {
  if (typeof str !== "string") {
    throw new TypeError("parseDate expects a string");
  }

  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(str);
  if (!match) {
    throw new RangeError("Date must use YYYY-MM-DD format");
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  // setUTCFullYear avoids Date.UTC treating years 0–99 as 1900–1999.
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);

  // Reject normalized invalid dates such as 2023-02-29 or 2023-13-01.
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    throw new RangeError("Invalid calendar date");
  }

  return date;
