// dates.js
// ISO-8601 calendar dates in YYYY-MM-DD format, represented at midnight UTC.

/**
 * Format a Date as an ISO-8601 calendar date.
 * @param {Date} date
 * @returns {string} YYYY-MM-DD
 */
export function formatDate(date) {
  if (!(date instanceof Date)) {
    throw new TypeError("date must be a Date");
  }
  if (Number.isNaN(date.getTime())) {
    throw new RangeError("date must be valid");
  }

  return date.toISOString().slice(0, 10);
}

/**
 * Parse a strict ISO-8601 calendar date.
 * @param {string} str YYYY-MM-DD
 * @returns {Date} A Date at midnight UTC
 */
export function parseDate(str) {
  if (typeof str !== "string") {
    throw new TypeError("str must be a string");
  }

  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(str);
  if (!match) {
    throw new RangeError("Date must use YYYY-MM-DD format");
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  if (month < 1 || month > 12) {
    throw new RangeError("Invalid month");
  }

  const isLeapYear = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const daysInMonth = [
    31, isLeapYear ? 29 : 28, 31, 30, 31, 30,
    31, 31, 30, 31, 30, 31,
  ];

  if (day < 1 || day > daysInMonth[month - 1]) {
    throw new RangeError("Invalid day");
  }

  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  date.setUTCHours(0, 0, 0, 0);
  return date;
}
