/**
 * Parse an ISO-8601 date or timestamp.
 * Date-only strings are interpreted as midnight UTC.
 */
export function parseDate(str) {
  if (typeof str !== "string") {
    throw new TypeError("str must be a string");
  }

  const match = ISO_8601_PATTERN.exec(str);
  if (!match) {
    throw new RangeError(`Invalid ISO-8601 date: ${str}`);
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const isLeapYear = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const daysInMonth = [
    31, isLeapYear ? 29 : 28, 31, 30, 31, 30,
    31, 31, 30, 31, 30, 31,
  ];

  if (month < 1 || month > 12 || day < 1 || day > daysInMonth[month - 1]) {
    throw new RangeError(`Invalid calendar date: ${str}`);
  }

  const date = new Date(str);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Invalid ISO-8601 date: ${str}`);
  }

  return date;
}
