 * Parses an ISO-8601 date string (YYYY-MM-DD) into a Date.
 * Uses UTC midnight to avoid timezone shift issues, and validates
 * the input strictly so e.g. "2023-02-30" or "2023-1-05" are rejected.
 *
 * @param {string} str - ISO-8601 date string.
 * @returns {Date} A Date object set to midnight UTC on that day.
 * @throws {TypeError} If str is not a string.
 * @throws {RangeError} If str is not a valid ISO-8601 date.
 */
function parseDate(str) {
  if (typeof str !== "string") {
    throw new TypeError(`Expected string, got ${typeof str}`);
  }

  // Strict match: exactly YYYY-MM-DD (basic sanity on ranges).
  const match = str.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) {
    throw new RangeError(`Invalid ISO-8601 date: "${str}"`);
