  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  if (month < 1 || month > 12) {
    throw new RangeError(`Invalid month in date: "${str}"`);
  }
  if (day < 1 || day > 31) {
    throw new RangeError(`Invalid day in date: "${str}"`);
  }

