  const [, y, mo, d, h = "0", mi = "0", s = "0", ms = "0", tz] = match;

  // Validate month/day ranges
  if (+mo < 1 || +mo > 12 || +d < 1 || +d > 31) {
    throw new RangeError(`Invalid ISO-8601 date string: ${str}`);
  }

  // Normalize timezone offset for Date constructor (e.g. +05:00 -> +05:00, +0500 -> +05:00)
  let normalized = str.replace(" ", "T");
  if (tz && tz !== "Z" && !tz.includes(":")) {
    normalized = normalized.replace(tz, `${tz.slice(0, 3)}:${tz.slice(3)}`);
  }
  if (ms.length < 3) {
    normalized = normalized.replace(`.${ms}`, `.${ms.padEnd(3, "0")}`);
  }

  const date = new Date(normalized);
  if (isNaN(date.getTime())) {
    throw new RangeError(`Invalid ISO-8601 date string: ${str}`);
  }
  return date;
}

module.exports = { formatDate, parseDate };

