 *
 * @param {number} a - Start value.
 * @param {number} b - End value.
 * @param {number} t - Interpolation factor.
 * @param {boolean} [clampT=false] - Clamp `t` to [0, 1] first.
 * @returns {number} The interpolated value.
 *
 * @example
 * lerp(0, 100, 0.25);            // 25
 * lerp(0, 100, 1.5);             // 150
 * lerp(0, 100, 1.5, true);       // 100
 */
export function lerp(a, b, t, clampT = false) {
  const factor = clampT ? clamp(t, 0, 1) : t;
  return a + (b - a) * factor;
}

/**
 * Return a random integer.
 *
 * With one argument, returns an integer in [0, max).
 * With two arguments, returns an integer in [min, max).
 *
 * @param {number} minOrMax - Upper bound (exclusive), or lower bound (inclusive).
 * @param {number} [max] - Upper bound (exclusive).
 * @returns {number} A random integer.
 * @throws {RangeError} If the range is empty or bounds are not integers.
 *
 * @example
 * randomInt(5);      // 0, 1, 2, 3, or 4
 * randomInt(10, 20); // 10 through 19
 */
export function randomInt(minOrMax, max) {
  const min = max === undefined ? 0 : minOrMax;
  const upper = max === undefined ? minOrMax : max;

  if (!Number.isInteger(min) || !Number.isInteger(upper)) {
    throw new RangeError('randomInt expects integer bounds');
  }
  if (upper <= min) {
