/**
 * slugify.js
 *
 * Utilities for turning arbitrary strings into URL-safe slugs.
 */

/**
 * Removes diacritical marks (accents) from a string.
 *
 * Uses Unicode normalization form NFD, which decomposes characters like
 * "é" into "e" + U+0301 (combining acute accent), then strips the
 * combining marks.
 *
 * @param {string} str - The input string.
 * @returns {string} The string with accents removed.
 */
function stripAccents(str) {
  if (typeof str !== 'string') {
    throw new TypeError('stripAccents expects a string');
  }
  return str.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

/**
 * Converts a string into a URL-friendly slug.
 *
 * Steps:
 *   1. Strip accents.
 *   2. Lowercase.
 *   3. Replace any run of non-alphanumeric characters with a single hyphen.
 *   4. Trim leading/trailing hyphens.
 *
 * @param {string} str - The input string.
 * @param {object} [options]
 * @param {string} [options.separator='-'] - Character(s) used to join words.
 * @param {boolean} [options.lower=true]   - Whether to lowercase the result.
 * @returns {string} The slugified string.
 */
function slugify(str, options = {}) {
  const { separator = '-', lower = true } = options;

  if (typeof str !== 'string') {
    throw new TypeError('slugify expects a string');
  }

  let result = stripAccents(str);

  if (lower) {
    result = result.toLowerCase();
  }

  // Replace anything that isn't a letter or digit with the separator.
  // \p{L} and \p{N} cover Unicode letters and numbers.
  result = result.replace(/[^\p{L}\p{N}]+/gu, separator);

  // Collapse repeated separators and trim from the ends.
  if (separator) {
    const escaped = separator.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    result = result
      .replace(new RegExp(`${escaped}{2,}`, 'g'), separator)
      .replace(new RegExp(`^${escaped}|${escaped}$`, 'g'), '');
  }

  return result;
}

module.exports = { slugify, stripAccents };
