// iso8601.js

/**
 * Pad a number to the given width with leading zeros.
 */
function pad(n, width = 2) {
  return String(n).padStart(width, '0');
}

/**
 * Format a Date (or date-like value) as an ISO-8601 string in UTC.
 * Output shape: YYYY-MM-DDTHH:mm:ss.sssZ
 *
 * @param {Date|number|string} date
 * @returns {string}
 */
function formatDate(date) {
  const d = date instanceof Date ? date : new Date(date);

  if (Number.isNaN(d.getTime())) {
    throw new TypeError('formatDate: invalid date');
  }

  const year = d.getUTCFullYear();
  const month = pad(d.getUTCMonth() + 1);
  const day = pad(d.getUTCDate());
  const hours = pad(d.getUTCHours());
  const minutes = pad(d.getUTCMinutes());
  const seconds = pad(d.getUTCSeconds());
  const millis = pad(d.getUTCMilliseconds(), 3);

  // Handle years outside 0000-9999 by using the expanded ±YYYYY form.
  const yearStr =
    year >= 0 && year <= 9999 ? pad(year, 4) : (year < 0 ? '-' : '+') + pad(Math.abs(year), 6);

  return `${yearStr}-${month}-${day}T${hours}:${minutes}:${seconds}.${millis}Z`;
}

// ISO-8601 patterns we accept.
const DATE_ONLY = /^(\d{4})-(\d{2})-(\d{2})$/;
const DATE_TIME =
  /^([+-]?\d{4,6})-(\d{2})-(\d{2})[Tt](\d{2}):(\d{2})(?::(\d{2})(?:\.(\d{1,9}))?)?([Zz]|[+-]\d{2}:?\d{2})?$/;

/**
 * Parse an ISO-8601 date string.
 *
 * Accepts:
 *   - "YYYY-MM-DD"                          (interpreted as UTC midnight)
 *   - "YYYY-MM-DDTHH:mm"                    (interpreted as UTC)
 *   - "YYYY-MM-DDTHH:mm:ss"
 *   - "YYYY-MM-DDTHH:mm:ss.sss"
 *   - Any of the above with a "Z" or ±HH:MM / ±HHMM offset
 *
 * @param {string} str
 * @returns {Date}
 */
function parseDate(str) {
  if (typeof str !== 'string') {
    throw new TypeError('parseDate: expected a string');
  }

  const trimmed = str.trim();

  const dateOnly = DATE_ONLY.exec(trimmed);
  if (dateOnly) {
    const [, y, m, d] = dateOnly;
    const date = new Date(Date.UTC(+y, +m - 1, +d));
    if (
      date.getUTCFullYear() !== +y ||
      date.getUTCMonth() !== +m - 1 ||
      date.getUTCDate() !== +d
    ) {
      throw new RangeError(`parseDate: invalid date "${str}"`);
    }
    return date;
  }

  const m = DATE_TIME.exec(trimmed);
  if (!m) {
    throw new RangeError(`parseDate: unrecognized ISO-8601 date "${str}"`);
  }

  const [, yearStr, monthStr, dayStr, hourStr, minStr, secStr, fracStr, tzStr] = m;

  const year = +yearStr;
  const month = +monthStr;
  const day = +dayStr;
  const hour = +hourStr;
  const minute = +minStr;
  const second = secStr ? +secStr : 0;

  // Milliseconds: take the first 3 fractional digits, pad the rest with zeros.
  let millis = 0;
  if (fracStr) {
    millis = +fracStr.slice(0, 3).padEnd(3, '0');
  }

  // Range validation (allow 60 for leap seconds by clamping).
  if (
    month < 1 || month > 12 ||
    day < 1 || day > 31 ||
    hour > 23 || minute > 59 || second > 60
  ) {
    throw new RangeError(`parseDate: out-of-range component in "${str}"`);
  }

  // Timezone offset in minutes.
  let offsetMinutes = 0;
  if (tzStr && tzStr.toUpperCase() !== 'Z') {
    const sign = tzStr[0] === '-' ? -1 : 1;
    const body = tzStr.slice(1).replace(':', '');
    const offH = +body.slice(0, 2);
    const offM = +body.slice(2, 4);
    if (offH > 23 || offM > 59) {
      throw new RangeError(`parseDate: invalid timezone offset in "${str}"`);
    }
    offsetMinutes = sign * (offH * 60 + offM);
  }

  // Build in UTC, then subtract the offset to get the true instant.
  const utcMs = Date.UTC(year, month - 1, day, hour, minute, second, millis);
  const date = new Date(utcMs - offsetMinutes * 60_000);

  // Reject dates like 2023-02-30 that JS rolls over silently.
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    throw new RangeError(`parseDate: invalid calendar date "${str}"`);
  }

  return date;
}

module.exports = { formatDate, parseDate };
```

