  if (typeof str !== 'string') {
    throw new TypeError('parseDate: expected a string');
  }

  const m = ISO_RE.exec(str.trim());
  if (!m) {
    throw new RangeError(`parseDate: invalid ISO-8601 date: ${str}`);
  }

  const [, year, month, day, hour = '00', minute = '00', second = '00', ms = '0', tz] = m;

  const y = Number(year);
  const mo = Number(month);
  const d = Number(day);
  const h = Number(hour);
  const mi = Number(minute);
  const s = Number(second);
  const milli = Number(ms.padEnd(3, '0'));

  // Basic range checks (Date.UTC would silently roll over otherwise).
  if (mo < 1 || mo > 12) throw new RangeError(`parseDate: month out of range: ${month}`);
  if (d < 1 || d > 31) throw new RangeError(`parseDate: day out of range: ${day}`);
  if (h > 23) throw new RangeError(`parseDate: hour out of range: ${hour}`);
  if (mi > 59) throw new RangeError(`parseDate: minute out of range: ${minute}`);
  if (s > 59) throw new RangeError(`parseDate: second out of range: ${second}`);

  let utcMs = Date.UTC(y, mo - 1, d, h, mi, s, milli);

  // Verify the calendar date is real (e.g. reject Feb 30).
  const check = new Date(utcMs);
  if (
    check.getUTCFullYear() !== y ||
    check.getUTCMonth() !== mo - 1 ||
    check.getUTCDate() !== d
  ) {
    throw new RangeError(`parseDate: invalid calendar date: ${str}`);
  }

  // Apply timezone offset if present.
  if (tz && tz !== 'Z') {
    const sign = tz[0] === '-' ? -1 : 1;
    const [oh, om] = tz.slice(1).replace(':', '').match(/\d{2}/g).map(Number);
    utcMs -= sign * (oh * 60 + om) * 60 * 1000;
  }

  return new Date(utcMs);
}

