  // Date-only: YYYY-MM-DD  ->  treat as UTC midnight
  const dateOnly = /^(\d{4})-(\d{2})-(\d{2})$/.exec(input);
  if (dateOnly) {
    const [, y, m, d] = dateOnly;
    const date = new Date(Date.UTC(+y, +m - 1, +d));
    if (
      date.getUTCFullYear() !== +y ||
      date.getUTCMonth() !== +m - 1 ||
      date.getUTCDate() !== +d
    ) {
      throw new TypeError(`parseDate: invalid calendar date: ${input}`);
    }
    return date;
  }

  // Full ISO-8601 timestamp (with optional fractional seconds and offset/Z)
  const timestamp =
    /^(\d{4})-(\d{2})-(\d{2})[Tt](\d{2}):(\d{2})(?::(\d{2})(?:\.(\d{1,9}))?)?(Z|z|[+-]\d{2}:?\d{2})?$/.exec(
      input
