    // for deterministic behavior across environments.
    const offsetMinutes = parseOffset(tz);

    const utcMs =
      Date.UTC(+y, +mo - 1, +d, +h, +mi, +s, ms) - offsetMinutes * 60_000;

    const date = new Date(utcMs);
    if (Number.isNaN(date.getTime())) {
      throw new TypeError(`parseDate: invalid date: ${input}`);
    }
