  if (!(date instanceof Date)) {
    throw new TypeError('formatDate: expected a Date instance');
  }
  if (Number.isNaN(date.getTime())) {
    throw new RangeError('formatDate: received an Invalid Date');
  }

  const pad = (n, width = 2) => String(n).padStart(width, '0');

  const year = date.getUTCFullYear();
  const month = date.getUTCMonth() + 1;
  const day = date.getUTCDate();
  const hours = date.getUTCHours();
  const minutes = date.getUTCMinutes();
  const seconds = date.getUTCSeconds();
  const ms = date.getUTCMilliseconds();

  // Only emit milliseconds if non-zero, matching common ISO-8601 output.
  const msPart = ms === 0 ? '' : '.' + pad(ms, 3);

  return (
    `${pad(year, 4)}-${pad(month)}-${pad(day)}` +
    `T${pad(hours)}:${pad(minutes)}:${pad(seconds)}${msPart}Z`
  );
}

/**
 * Parse an ISO-8601 string into a Date.
 * @param {string} str
 * @returns {Date}
 */
function parseDate(str) {
  if (typeof str !== 'string') {
    throw new TypeError('parseDate: expected a string');
  }

  const match = ISO_RE.exec(str);
  if (!match) {
    throw new RangeError(`parseDate: not a valid ISO-8601 date: ${str}`);
  }

  const [
    ,
    yearStr,
    monthStr,
    dayStr,
    hourStr = '00',
    minStr = '00',
    secStr = '00',
    fracStr = '',
    tz = 'Z',
  ] = match;

  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);
  const hours = Number(hourStr);
  const minutes = Number(minStr);
  const seconds = Number(secStr);

  // Validate ranges (day is checked against the actual month below).
  if (month < 1 || month > 12) {
    throw new RangeError(`parseDate: month out of range: ${monthStr}`);
  }
  if (hours > 23 || minutes > 59 || seconds > 59) {
    throw new RangeError(`parseDate: time out of range: ${str}`);
  }

  // Milliseconds, truncated to 3 digits (ISO allows more).
  const ms = fracStr ? Number(fracStr.slice(0, 3).padEnd(3, '0')) : 0;

  // Convert timezone offset to minutes.
  let offsetMinutes = 0;
  if (tz !== 'Z') {
    const sign = tz[0] === '-' ? -1 : 1;
    const tzHours = Number(tz.slice(1, 3));
    const tzMins = Number(tz.slice(4, 6));
    offsetMinutes = sign * (tzHours * 60 + tzMins);
  }

  // Build the timestamp in UTC, then subtract the offset to get the real instant.
  const utcMs = Date.UTC(year, month - 1, day, hours, minutes, seconds, ms);
  const time = utcMs - offsetMinutes * 60_000;

  const result = new Date(time);

  // Guard against overflow (e.g. 2024-02-31 rolling into March).
  if (
    result.getUTCFullYear() !== year ||
    result.getUTCMonth() + 1 !== month ||
    result.getUTCDate() !== day
