## Notes on design choices

- **`formatDate` always outputs UTC** with a trailing `Z`. This is the safest default — local-time formatting invites DST bugs.
- **Milliseconds are omitted when zero** to keep output tidy, but the format is still valid ISO-8601 either way.
- **`parseDate` rejects invalid calendar dates** like `2024-02-31` that `Date.UTC` would silently roll over. Native `Date.parse` accepts those on some engines and rejects them on others, so being explicit is better.
- **`parseDate` returns a `Date` in local-time representation** of the correct instant — the `Date` object itself has no timezone, so this is the only sensible return type.
- The regex is intentionally a bit stricter than `Date.parse`, but it covers everything RFC 3339 / ISO-8601 actually produces in practice.

```js
/**
 * Format a Date as an ISO-8601 date string (YYYY-MM-DD).
 * Uses UTC components so the result is timezone-independent.
 *
 * @param {Date} date
 * @returns {string}
 */
export function formatDate(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    throw new TypeError('formatDate expects a valid Date object');
  }

  const year = String(date.getUTCFullYear()).padStart(4, '0');
  const month = String(date.getUTCMonth() + 1).padStart(2, '0');
  const day = String(date.getUTCDate()).padStart(2, '0');

  return `${year}-${month}-${day}`;
}

/**
 * Parse an ISO-8601 date string (YYYY-MM-DD) into a Date at UTC midnight.
 *
 * @param {string} str
 * @returns {Date}
 */
export function parseDate(str) {
  if (typeof str !== 'string') {
    throw new TypeError('parseDate expects a string');
  }

  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(str);
  if (!match) {
    throw new RangeError('Invalid ISO-8601 date string');
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  if (month < 1 || month > 12) {
    throw new RangeError('Invalid month');
  }

  if (day < 1 || day > daysInMonth(year, month)) {
    throw new RangeError('Invalid day');
  }

  const date = new Date(0);
  date.setUTCHours(0, 0, 0, 0);
  date.setUTCFullYear(year, month - 1, day);

  return date;
}

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year, month) {
  switch (month) {
    case 2:
      return isLeapYear(year) ? 29 : 28;
    case 4:
    case 6:
    case 9:
    case 11:
      return 30;
    default:
      return 31;
  }
}
