 * Format a Date as an ISO-8601 string in UTC (e.g. "2024-01-15T12:30:45.123Z").
 *
 * @param {Date} date
 * @returns {string}
 * @throws {TypeError} if the argument is not a valid Date
 */
export function formatDate(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    throw new TypeError('formatDate: expected a valid Date');
  }
  return date.toISOString();
}

export default { formatDate, parseDate };
