 * Parse an ISO-8601 date string into a Date.
 * - Date-only strings ("2024-01-15") are interpreted as UTC midnight.
 * - Datetimes without a timezone designator are interpreted as UTC.
 * @param {string} str
 * @returns {Date}
 */
export function parseDate(str) {
  if (typeof str !== 'string') {
    throw new TypeError('parseDate: expected a string');
  }

  const m = ISO_8601.exec(str);
  if (!m) {
    throw new RangeError(`parseDate: not a valid ISO-8601 date: ${str}`);
  }

  const [, yearStr, monthStr, dayStr, hourStr, minuteStr, secondStr, , tz] = m;

  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);

  if (month < 1 || month > 12) {
    throw new RangeError(`parseDate: invalid month in "${str}"`);
  }
  const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
  if (day < 1 || day > daysInMonth) {
    throw new RangeError(`parseDate: invalid day in "${str}"`);
  }

  if (hourStr !== undefined) {
    const hour = Number(hourStr);
    const minute = Number(minuteStr);
    if (hour > 23) {
      throw new RangeError(`parseDate: invalid hour in "${str}"`);
    }
    if (minute > 59) {
      throw new RangeError(`parseDate: invalid minute in "${str}"`);
    }
    if (secondStr !== undefined && Number(secondStr) > 59) {
      throw new RangeError(`parseDate: invalid second in "${str}"`);
    }
  }

  // Normalize to a fully-specified UTC string so the Date constructor
  // doesn't fall back to local time for date-only / offset-less input.
  let normalized = str;
  if (hourStr === undefined) {
    normalized = `${str}T00:00:00.000Z`;
  } else if (tz === undefined) {
    normalized = `${str}Z`;
  }

  const date = new Date(normalized);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`parseDate: invalid date "${str}"`);
  }
  return date;
}
