/**
 * Format a Date (or timestamp) as an ISO-8601 date string.
 *
 * By default produces a calendar date: "YYYY-MM-DD".
 * Pass `{ time: true }` to include the UTC time: "YYYY-MM-DDTHH:mm:ss.sssZ".
 *
 * @param {Date|number|string} date - Date object, epoch ms, or parseable string.
 * @param {{ time?: boolean }} [options]
 * @returns {string}
