// isoDate.js
//
// Minimal helpers for ISO-8601 calendar dates (YYYY-MM-DD).
//
//   formatDate(date) -> "YYYY-MM-DD"
//   parseDate(str)   -> Date (at UTC midnight) or null if invalid
//
// The functions operate in UTC so that a date like "2024-02-29" round-trips
// exactly regardless of the local time zone.

'use strict';

/**
 * Format a Date (or timestamp) as an ISO-8601 calendar date.
 *
 * @param {Date|number} date
 * @returns {string} e.g. "2024-02-29"
 * @throws {TypeError} if `date` is not a valid Date/number.
 */
function formatDate(date) {
  const d = date instanceof Date ? date : new Date(date);

  if (!(d instanceof Date) || Number.isNaN(d.getTime())) {
    throw new TypeError('formatDate: expected a valid Date or timestamp');
  }

  const year = d.getUTCFullYear();
  const month = d.getUTCMonth() + 1;
  const day = d.getUTCDate();

  return (
    String(year).padStart(4, '0') +
    '-' +
    String(month).padStart(2, '0') +
    '-' +
    String(day).padStart(2, '0')
  );
}

/**
 * Parse an ISO-8601 calendar date string into a Date at UTC midnight.
 *
 * Accepts "YYYY-MM-DD" and the extended form "YYYY-MM-DDTHH:mm:ss(.sss)?Z"
 * (other ISO-8601 time components are tolerated). Returns `null` for
 * anything that is not a valid date.
 *
 * @param {string} str
 * @returns {Date|null}
 */
function parseDate(str) {
  if (typeof str !== 'string') return null;

  const match = /^(\d{4})-(\d{2})-(\d{2})(?:$|[T\s])/.exec(str.trim());
  if (!match) return null;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  if (month < 1 || month > 12) return null;
  if (day < 1 || day > 31) return null;

  // Build the date in UTC and verify the components survived (catches
  // e.g. "2023-02-30" which JS would otherwise roll into March).
  const date = new Date(Date.UTC(year, month - 1, day));

  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return null;
  }

  return date;
}

module.exports = { formatDate, parseDate };
