## `utils.js`

```js
/**
 * Small numeric utilities: clamp, lerp, randomInt.
 *
 * @module utils
 */

/* -------------------------------------------------------------------------- */
/* Internal helpers                                                           */
/* -------------------------------------------------------------------------- */

const UINT32_RANGE = 0x100000000; // 2^32
const SAFE_RANGE = 0x20000000000000; // 2^53

/**
 * `globalThis.crypto` when available (browsers, Node >= 19), otherwise null.
 * Used as a source of unbiased random bits; falls back to Math.random.
 */
const webCrypto =
  typeof globalThis !== 'undefined' &&
  globalThis.crypto &&
  typeof globalThis.crypto.getRandomValues === 'function'
    ? globalThis.crypto
    : null;

/** @returns {number} A uniformly distributed integer in [0, 2^32). */
function randomUint32() {
  if (webCrypto) {
    const buf = new Uint32Array(1);
    webCrypto.getRandomValues(buf);
    return buf[0];
  }
  // Math.random() carries ~52 bits of entropy, so this is still uniform.
  return Math.floor(Math.random() * UINT32_RANGE);
}

/**
 * A uniformly distributed integer in [0, range) with no modulo bias.
 *
 * Uses rejection sampling: values are drawn from a power-of-two space and
 * discarded until they fall below the largest multiple of `range` that fits.
 *
 * @param {number} range - Exclusive upper bound; must be >= 1.
 * @returns {number}
 */
function randomBelow(range) {
  if (range <= UINT32_RANGE) {
    const limit = Math.floor(UINT32_RANGE / range) * range;
    let value;
    do {
      value = randomUint32();
    } while (value >= limit);
    return value % range;
  }

  if (range > SAFE_RANGE) {
    throw new RangeError(
      `randomInt: range of ${range} exceeds the safe integer limit`,
    );
  }

  // 21 high bits + 32 low bits = 53 bits, exactly representable as a Number.
  const limit = Math.floor(SAFE_RANGE / range) * range;
  let value;
  do {
    const high = randomUint32() & 0x1fffff;
    const low = randomUint32();
    value = high * UINT32_RANGE + low;
  } while (value >= limit);
  return value % range;
}

/* -------------------------------------------------------------------------- */
/* Public API                                                                 */
/* -------------------------------------------------------------------------- */

/**
 * Constrain `value` to the inclusive range [min, max].
 *
 * If `min > max` the bounds are swapped, so the result is always within the
 * interval spanned by the two arguments. A `NaN` value propagates as `NaN`.
 *
 * @param {number} value
 * @param {number} min
 * @param {number} max
 * @returns {number}
 * @throws {TypeError} If `min` or `max` is NaN.
 */
export function clamp(value, min, max) {
  if (Number.isNaN(min) || Number.isNaN(max)) {
    throw new TypeError('clamp: min and max must not be NaN');
  }
  if (Number.isNaN(value)) return NaN;

  const lo = min <= max ? min : max;
  const hi = min <= max ? max : min;

  if (value < lo) return lo;
  if (value > hi) return hi;
  return value;
}

/**
 * Linear interpolation between `a` and `b`.
 *
 * `t` is *not* clamped: values outside [0, 1] extrapolate along the same line.
 *
 * @param {number} a - Value at t = 0.
 * @param {number} b - Value at t = 1.
 * @param {number} t - Interpolation factor.
 * @returns {number}
 */
export function lerp(a, b, t) {
  return a + (b - a) * t;
}

/**
 * A random integer in the inclusive range [min, max].
 *
 * Non-integer bounds are tightened inward (min rounded up, max rounded down),
 * so the result is always an integer inside the original interval.
 *
 * @param {number} min - Inclusive lower bound.
 * @param {number} max - Inclusive upper bound.
 * @returns {number}
 * @throws {TypeError} If either bound is not finite.
 * @throws {RangeError} If `min > max`, or the range exceeds 2^53.
 */
export function randomInt(min, max) {
  if (!Number.isFinite(min) || !Number.isFinite(max)) {
    throw new TypeError('randomInt: min and max must be finite numbers');
  }

  const lo = Math.ceil(min);
  const hi = Math.floor(max);

  if (lo > hi) {
    throw new RangeError(
      `randomInt: min (${min}) must not be greater than max (${max})`,
    );
  }

  return lo + randomBelow(hi - lo + 1);
}

export default { clamp, lerp, randomInt };
```

## Usage

```js
import { clamp, lerp, randomInt } from './utils.js';

clamp(150, 0, 100);   // 100
clamp(-5, 0, 100);    // 0
clamp(42, 0, 100);    // 42
clamp(5, 100, 0);     // 5   (bounds swapped)

lerp(0, 10, 0.5);     // 5
lerp(0, 10, 2);       // 20  (extrapolates)

randomInt(1, 6);      // 1..6 inclusive — a fair die roll
randomInt(0, 0);      // 0
```

## Design notes

- **`clamp`** swaps reversed bounds rather than throwing, since "clamp to the interval between these two numbers" is the more common intent. `NaN` in the *value* propagates; `NaN` in a *bound* throws, because that's always a bug.
- **`lerp`** uses `a + (b - a) * t` and deliberately leaves `t` unclamped so it can be used for extrapolation. If you want a clamped variant, `lerp(a, b, clamp(t, 0, 1))` does it.
- **`randomInt`** uses rejection sampling instead of `Math.floor(Math.random() * n) + min`, which is biased whenever `n` doesn't divide the RNG's range evenly (e.g. `randomInt(0, 5)` with a 32-bit source would make 0 twice as likely as 1). It prefers `crypto.getRandomValues` and falls back to `Math.random` where the Web Crypto API isn't available.

