## `utils.js`

```js
/**
 * Small numeric utilities: clamp, lerp, randomInt.
 *
 * ES module. Works in browsers and Node (>= 18 for the crypto-backed RNG,
 * with a Math.random fallback for older runtimes).
 */

/* ------------------------------------------------------------------ *
 * clamp
 * ------------------------------------------------------------------ */

/**
 * Constrain `value` to the inclusive range [min, max].
 *
 * - If `min > max` the bounds are swapped, so the call is still well-defined.
 * - `NaN` input propagates: `clamp(NaN, 0, 10) === NaN`.
 *
 * @param {number} value
 * @param {number} min
 * @param {number} max
 * @returns {number}
 */
export function clamp(value, min, max) {
  if (min > max) {
    const swap = min;
    min = max;
    max = swap;
  }
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

/* ------------------------------------------------------------------ *
 * lerp
 * ------------------------------------------------------------------ */

/**
 * Linear interpolation between `start` and `end`.
 *
 * `t` is NOT clamped: t = 0 -> start, t = 1 -> end, t < 0 or t > 1
 * extrapolates beyond the endpoints. Use `clamp(t, 0, 1)` first if you
 * want the result pinned to the segment.
 *
 * @param {number} start
 * @param {number} end
 * @param {number} t
 * @returns {number}
 */
export function lerp(start, end, t) {
  return start + (end - start) * t;
}

/* ------------------------------------------------------------------ *
 * randomInt
 * ------------------------------------------------------------------ */

const UINT32_RANGE = 0x1_0000_0000; // 2^32
const RANDOM_SPACE = Number.MAX_SAFE_INTEGER + 1; // 2^53

/** @returns {boolean} true if a CSPRNG is reachable. */
function hasCrypto() {
  return (
    typeof globalThis !== 'undefined' &&
    globalThis.crypto != null &&
    typeof globalThis.crypto.getRandomValues === 'function'
  );
}

/**
 * Uniform integer in [0, 2^53).
 * @returns {number}
 */
function randomUint53() {
  if (hasCrypto()) {
    const buf = new Uint32Array(2);
    globalThis.crypto.getRandomValues(buf);
    // 21 high bits + 32 low bits = 53 bits, no float rounding loss.
    return (buf[0] >>> 11) * UINT32_RANGE + buf[1];
  }
  return Math.floor(Math.random() * RANDOM_SPACE);
}

/**
 * Uniform integer in [0, limit) using rejection sampling, so the result
 * is free of the modulo bias a plain `%` would introduce.
 * @param {number} limit 1 <= limit <= 2^53
 * @returns {number}
 */
function randomBelow(limit) {
  if (limit <= 1) return 0;
  const bucket = Math.floor(RANDOM_SPACE / limit) * limit;
  let value;
  do {
    value = randomUint53();
  } while (value >= bucket);
  return value % limit;
}

/**
 * Random integer in the inclusive range [min, max].
 *
 * - Both bounds must be integers (throws TypeError otherwise).
 * - If `min > max` the bounds are swapped.
 * - The span must fit in the safe-integer range (throws RangeError otherwise).
 * - Backed by `crypto.getRandomValues` when available, so it is suitable
 *   for security-sensitive uses (tokens, ids, shuffles).
 *
 * @param {number} min
 * @param {number} max
 * @returns {number}
 */
export function randomInt(min, max) {
  if (!Number.isInteger(min) || !Number.isInteger(max)) {
    throw new TypeError('randomInt(min, max): both arguments must be integers');
  }
  if (min > max) {
    const swap = min;
    min = max;
    max = swap;
  }
  const span = max - min;
  if (span > Number.MAX_SAFE_INTEGER) {
    throw new RangeError('randomInt(min, max): range exceeds safe integer limits');
  }
  return min + randomBelow(span + 1);
}

export default { clamp, lerp, randomInt };
```

