/**
 * Small numeric helpers: clamping, interpolation, and random integers.
 * @module utils/numbers
 */

/**
 * Restricts `value` to the inclusive range `[min, max]`.
 *
 * If `min > max` the bounds are swapped, so the call never throws.
 *
 * @param {number} value - Value to constrain.
 * @param {number} min - Lower bound.
 * @param {number} max - Upper bound.
 * @returns {number} `value`, or the nearest bound it exceeds.
 * @example
 * clamp(12, 0, 10);   // 10
 * clamp(-3, 0, 10);   // 0
 * clamp(5, 0, 10);    // 5
 */
export function clamp(value, min, max) {
  if (min > max) {
    const tmp = min;
    min = max;
    max = tmp;
  }
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

/**
 * Linearly interpolates between `a` and `b`.
 *
 * `t = 0` yields `a`, `t = 1` yields `b`. Values outside `[0, 1]` extrapolate
 * unless `clampT` is set, in which case `t` is clamped first.
 *
 * @param {number} a - Start value.
 * @param {number} b - End value.
 * @param {number} t - Interpolation factor.
 * @param {{ clampT?: boolean }} [options] - Optional settings.
 * @returns {number} The interpolated value.
 * @example
 * lerp(0, 10, 0.25);   // 2.5
 * lerp(0, 10, 1.5);    // 15 (extrapolated)
 * lerp(0, 10, 1.5, { clampT: true }); // 10
 */
export function lerp(a, b, t, options = {}) {
  const factor = options.clampT ? clamp(t, 0, 1) : t;
  return a + (b - a) * factor;
}

/**
 * Returns a random integer in the inclusive range `[min, max]`.
 *
 * Uses `crypto.getRandomValues` with rejection sampling when available, which
 * avoids the modulo bias of `Math.random()`. Falls back to `Math.random()`
 * otherwise. Fractional bounds are floored/ceiled to integers.
 *
 * @param {number} min - Lower bound (inclusive).
 * @param {number} max - Upper bound (inclusive).
 * @returns {number} A uniformly distributed integer in `[min, max]`.
 * @throws {TypeError} If either bound is not a finite number.
 * @throws {RangeError} If `max < min`.
 * @example
 * randomInt(1, 6);   // 1..6
 * randomInt(0, 0);   // 0
 */
export function randomInt(min, max) {
  if (!Number.isFinite(min) || !Number.isFinite(max)) {
    throw new TypeError('randomInt: min and max must be finite numbers');
  }

  const lo = Math.ceil(min);
  const hi = Math.floor(max);

  if (hi < lo) {
    throw new RangeError('randomInt: max must be greater than or equal to min');
  }

  const range = hi - lo + 1;
  if (range === 1) return lo;

  const cryptoObj = globalThis.crypto;
  if (cryptoObj && typeof cryptoObj.getRandomValues === 'function') {
    // Largest multiple of `range` that fits in a uint32; values at or above
    // it are discarded so the modulo below stays uniform.
    const limit = Math.floor(0x1_0000_0000 / range) * range;
    const buffer = new Uint32Array(1);
    let draw;
    do {
      cryptoObj.getRandomValues(buffer);
      draw = buffer[0];
    } while (draw >= limit);
    return lo + (draw % range);
  }

  return lo + Math.floor(Math.random() * range);
}

export default { clamp, lerp, randomInt };
```

