```js
/**
 * Small numeric helpers: clamp, lerp, randomInt.
 *
 * @module utils/math
 */

/**
 * Constrain `value` to the inclusive range `[min, max]`.
 *
 * @param {number} value
 * @param {number} min
 * @param {number} max
 * @returns {number} `value`, or the nearest bound if it is out of range.
 * @throws {RangeError} if `min > max`.
 *
 * @example
 * clamp(5, 0, 10);   // 5
 * clamp(-3, 0, 10);  // 0
 * clamp(42, 0, 10);  // 10
 */
export function clamp(value, min, max) {
  if (min > max) {
    throw new RangeError(`clamp: min (${min}) must be <= max (${max})`);
  }
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

/**
 * Linear interpolation between `a` and `b`.
 *
 * `t` is *not* clamped: values outside `[0, 1]` extrapolate along the line
 * through `a` and `b`.
 *
 * @param {number} a Value at `t === 0`.
 * @param {number} b Value at `t === 1`.
 * @param {number} t Interpolation factor.
 * @returns {number}
 *
 * @example
 * lerp(0, 10, 0.5);  // 5
 * lerp(0, 10, 2);    // 20 (extrapolated)
 */
export function lerp(a, b, t) {
  return a + (b - a) * t;
}

/**
 * Largest multiple of `n` that fits in 53 bits, used for unbiased rejection
 * sampling.
 */
const TWO_POW_53 = 2 ** 53;

/**
 * A uniformly random integer in `[0, 2**53)`.
 *
 * Uses `crypto.getRandomValues` when available (browsers in secure contexts,
 * Node >= 19) and falls back to `Math.random` otherwise.
 *
 * @param {number} n Exclusive upper bound; must be a positive integer.
 * @returns {number} Integer in `[0, n)`.
 */
function randomBelow(n) {
  const cryptoObj = globalThis.crypto;

  if (cryptoObj && typeof cryptoObj.getRandomValues === 'function') {
    const buf = new Uint32Array(2);
    // Reject the tail of the range so every outcome is equally likely
    // (no modulo bias).
    const limit = Math.floor(TWO_POW_53 / n) * n;
    let x;
    do {
      cryptoObj.getRandomValues(buf);
      // Combine two 32-bit words into one 53-bit integer.
      x = buf[0] * 2 ** 21 + (buf[1] >>> 11);
    } while (x >= limit);
    return x % n;
  }

  return Math.floor(Math.random() * n);
}

/**
 * A uniformly random integer in the inclusive range `[min, max]`.
 *
 * @param {number} min Inclusive lower bound; must be a safe integer.
 * @param {number} max Inclusive upper bound; must be a safe integer.
 * @returns {number}
 * @throws {RangeError} if the bounds are not safe integers or `min > max`.
 *
 * @example
 * randomInt(1, 6);    // 1..6, like a die roll
 * randomInt(0, 0);    // 0
 */
export function randomInt(min, max) {
  if (!Number.isSafeInteger(min) || !Number.isSafeInteger(max)) {
    throw new RangeError('randomInt: min and max must be safe integers');
  }
  if (min > max) {
    throw new RangeError(`randomInt: min (${min}) must be <= max (${max})`);
  }
  if (min === max) return min;

  return min + randomBelow(max - min + 1);
}
```

