  ? /\p{M}/gu
  : /[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20f0\ufe20-\ufe2f]/g;

/** Anything that is not a letter or a number. */
const NON_ALPHANUMERIC = SUPPORTS_UNICODE_PROPERTIES
  ? /[^\p{L}\p{N}]+/gu
  : /[^a-z0-9]+/g;

/**
 * Letters that do NOT decompose into "base letter + combining mark" when
 * normalized with NFD, so they need an explicit replacement.
 */
const NON_DECOMPOSING = {
  'Æ': 'AE', 'æ': 'ae',
  'Œ': 'OE', 'œ': 'oe',
  'ß': 'ss', 'ẞ': 'SS',
  'Ø': 'O',  'ø': 'o',
  'Đ': 'D',  'đ': 'd',
  'Ð': 'D',  'ð': 'd',
  'Þ': 'TH', 'þ': 'th',
  'Ł': 'L',  'ł': 'l',
  'Ħ': 'H',  'ħ': 'h',
  'Ŋ': 'N',  'ŋ': 'n',
  'Ĳ': 'IJ', 'ĳ': 'ij',
  'ı': 'i',  'ſ': 's',
};

const NON_DECOMPOSING_CHARS = new RegExp(
  '[' + Object.keys(NON_DECOMPOSING).join('') + ']',
  'g'
);

/* -------------------------------------------------------------------------
 * Public API
 * ---------------------------------------------------------------------- */

/**
 * Remove diacritical marks (accents) from a string.
 *
 * The original casing is preserved.
 *
 * @param {string} str  Input text.
 * @returns {string}    Text without accents.
 */
export function stripAccents(str) {
  if (str === null || str === undefined) return '';

  let out = String(str);

  // Decompose "é" into "e" + combining acute accent.
  if (typeof out.normalize === 'function') {
    out = out.normalize('NFD');
  }

  // Drop the combining marks.
  out = out.replace(COMBINING_MARKS, '');

  // Handle letters that cannot be decomposed.
  out = out.replace(NON_DECOMPOSING_CHARS, (ch) => NON_DECOMPOSING[ch]);

  return out;
