  if (str === null || str === undefined) return '';

  let s = String(str);

  // 1. Explicit transliterations for letters that don't decompose.
  s = s.replace(SPECIAL_LETTERS_RE, (ch) => SPECIAL_LETTERS[ch] ?? ch);

  // 2. Decompose + strip combining marks + recompose.
  if (typeof s.normalize === 'function') {
    s = s.normalize('NFD').replace(COMBINING_MARKS, '').normalize('NFC');
  }

  return s;
