/**
 * Convert a string into a URL-friendly slug.
 *
 * @param {*} str
 *   The text to slugify.
 * @param {Object} [options]
 * @param {string} [options.separator='-']   Character(s) used between words.
 * @param {boolean} [options.lowerCase=true]  Lowercase the result.
 * @param {boolean} [options.trim=true]       Remove leading/trailing separators.
 * @param {boolean} [options.strict=false]    Restrict output to [a-z0-9].
 * @param {Object} [options.replacements={}]  Custom char -> string map applied
 *                                            before slugging (e.g. { '&': 'and' }).
 * @returns {string}
 */
export function slugify(str, options = {}) {
  const {
    separator = '-',
    lowerCase = true,
    trim = true,
    strict = false,
    replacements = {},
  } = options;

  if (str === null || str === undefined) return '';

  let s = String(str);

  // 1. User supplied replacements (e.g. '&' -> 'and').
  for (const [from, to] of Object.entries(replacements)) {
    if (from) s = s.split(from).join(to);
  }

  // 2. Drop accents.
  s = stripAccents(s);

  // 3. Case.
  if (lowerCase) s = s.toLowerCase();

  // 4. Replace every run of non-alphanumeric characters with the separator.
  const pattern = strict || !SUPPORTS_UNICODE_PROPERTIES ? NON_WORD_ASCII : NON_WORD_UNICODE;
  s = s.replace(pattern, () => separator);

  // 5. Collapse repeated separators and trim the edges.
  if (separator) {
    const sep = escapeRegExp(separator);
    s = s.replace(new RegExp(`(?:${sep}){2,}`, 'g'), () => separator);
    if (trim) {
      s = s.replace(new RegExp(`^${sep}+|${sep}+$`, 'g'), '');
    }
  }

  return s;
}

export default slugify;
