  return month === 2 && isLeapYear(year) ? 29 : DAYS_IN_MONTH[month - 1];
}

/**
 * Format a Date as an ISO-8601 string, e.g. "2024-02-29T12:00:00.000Z".
 *
 * @param {Date} date
 * @returns {string}
 * @throws {TypeError} if `date` is not a Date instance
 * @throws {RangeError} if `date` is an Invalid Date
 */
export function formatDate(date) {
  if (!(date instanceof Date)) {
    throw new TypeError('formatDate(date): expected a Date instance');
  }
  if (Number.isNaN(date.getTime())) {
    throw new RangeError('formatDate(date): cannot format an Invalid Date');
  }
  return date.toISOString();
}

/**
 * Parse an ISO-8601 string into a Date.
 *
 * Accepted shapes:
 *   2024
 *   2024-02
 *   2024-02-29
 *   2024-02-29T12:00
 *   2024-02-29T12:00:00
 *   2024-02-29T12:00:00.123
 *   2024-02-29T12:00:00Z
 *   2024-02-29T12:00:00+02:00
 *
 * @param {string} str
 * @returns {Date}
 * @throws {TypeError} if `str` is not a string
 * @throws {RangeError} if `str` is not a valid ISO-8601 date
 */
export function parseDate(str) {
  if (typeof str !== 'string') {
    throw new TypeError('parseDate(str): expected a string');
  }

  const match = ISO_8601.exec(str.trim());
  if (!match) {
    throw new RangeError(`parseDate(str): "${str}" is not a valid ISO-8601 date`);
  }

  const [, y, mo, d, h, mi, s, frac, zone] = match;

  const year = Number(y);
  const month = Number(mo);
  const day = Number(d);
  const hour = h === undefined ? 0 : Number(h);
  const minute = mi === undefined ? 0 : Number(mi);
  const second = s === undefined ? 0 : Number(s);
  const millis = frac ? Number(frac.slice(0, 3).padEnd(3, '0')) : 0;

  if (month < 1 || month > 12) {
    throw new RangeError(`parseDate(str): month out of range in "${str}"`);
  }
  if (day < 1 || day > daysInMonth(year, month)) {
    throw new RangeError(`parseDate(str): day out of range in "${str}"`);
  }
  if (hour > 23 || minute > 59 || second > 59) {
    throw new RangeError(`parseDate(str): time out of range in "${str}"`);
  }

  // Build the date in UTC. setUTCFullYear avoids the 0–99 => 1900+year quirk.
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  date.setUTCHours(hour, minute, second, millis);

  // Guard against any silent rollover.
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    throw new RangeError(`parseDate(str): invalid date "${str}"`);
  }

  // Apply a numeric UTC offset (e.g. "+02:00" -> subtract 2 hours from UTC).
  if (zone && zone.toUpperCase() !== 'Z') {
    const sign = zone[0] === '+' ? 1 : -1;
    const digits = zone.slice(1).replace(':', '');
    const offsetMinutes =
      sign * (Number(digits.slice(0, 2)) * 60 + Number(digits.slice(2, 4)));
    date.setTime(date.getTime() + offsetMinutes * 60_000);
  }

  return date;
}

export default { formatDate, parseDate };
```

### Example usage

```js
import { formatDate, parseDate } from './date-utils.js';

formatDate(new Date(Date.UTC(2024, 1, 29, 12, 0, 0)));
// "2024-02-29T12:00:00.000Z"

parseDate('2024-02-29T12:00:00Z');        // Date 2024-02-29T12:00:00.000Z
parseDate('2024-02-29T12:00:00+02:00');   // Date 2024-02-29T10:00:00.000Z
parseDate('2024-02-29');                   // Date 2024-02-29T00:00:00.000Z

parseDate('2023-02-29');                   // throws RangeError (not a leap year)
parseDate('not-a-date');                   // throws RangeError
```

**Notes**
- `formatDate` always emits UTC with a `Z` suffix and millisecond precision (`Date.prototype.toISOString`).
- `parseDate` is strict: it validates calendar correctness (month lengths, leap years) and time ranges rather than silently rolling over invalid dates like `new Date('2023-02-29')` does.
- Leap seconds (`:60`) are rejected, since `Date` cannot represent them.

# `iso-date.js`

```js
/**
 * iso-date.js — small, dependency-free ISO-8601 date helpers.
 *
 *   import { formatDate, parseDate } from './iso-date.js';
 *
 *   formatDate(new Date());                       // '2024-02-29'
 *   formatDate(new Date(), { precision: 'second' }); // '2024-02-29T12:34:56Z'
 *   parseDate('2024-02-29');                      // Date → 2024-02-29T00:00:00Z
 *   parseDate('2024-02-29T12:00:00+02:00');       // Date → 2024-02-29T10:00:00Z
 *
 * Behaviour notes
 * ---------------
 * - Formatting defaults to UTC so output never depends on the host timezone.
 *   Pass { timezone: 'local' } for local time (a numeric offset is appended).
 * - Date-only strings ('2024-02-29') are read as UTC midnight by default;
 *   pass { timezone: 'local' } to read them as local midnight.
 * - Parsing is strict: malformed or impossible dates ('2023-02-29',
 *   '2024-13-01', 'not-a-date') throw a RangeError instead of being silently
 *   rolled over the way `new Date('2024-13-01')` does.
 */

/* ------------------------------------------------------------------ *
 * Patterns
 * ------------------------------------------------------------------ */

/** YYYY-MM-DD */
const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * YYYY-MM-DD[Tt ]HH[:mm[:ss[.fraction]]][Z|±hh[:]mm]
 * The zone designator is optional; when absent the value is interpreted
 * according to `options.timezone` (UTC by default).
 */
const DATE_TIME_RE =
  /^(\d{4})-(\d{2})-(\d{2})[Tt ](\d{2})(?::(\d{2})(?::(\d{2})(?:\.(\d{1,9}))?)?)?(Z|z|[+-]\d{2}(?::?\d{2})?)?$/;

const PRECISIONS = new Set(['day', 'minute', 'second', 'millisecond']);

/* ------------------------------------------------------------------ *
 * Internal helpers
 * ------------------------------------------------------------------ */

function pad(value, width = 2) {
  return String(value).padStart(width, '0');
}

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year, month) {
  return [31, isLeapYear(year) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
}

function assertValidYmd(year, month, day) {
  if (month < 1 || month > 12) {
    throw new RangeError(`Invalid month ${month} (expected 1-12)`);
  }
  if (day < 1 || day > daysInMonth(year, month)) {
    throw new RangeError(`Invalid day ${day} for ${year}-${pad(month)}`);
  }
}

/**
 * Build a UTC timestamp. Uses setUTCFullYear so years 0-99 are not
 * remapped to 1900+year the way Date.UTC() does.
 */
function utcMillis(year, month, day, hour = 0, minute = 0, second = 0, ms = 0) {
  const d = new Date(0);
  d.setUTCFullYear(year, month - 1, day);
  d.setUTCHours(hour, minute, second, ms);
  return d.getTime();
}

/** Same as utcMillis() but in the host's local timezone. */
function localMillis(year, month, day, hour = 0, minute = 0, second = 0, ms = 0) {
  const d = new Date(0);
  d.setFullYear(year, month - 1, day);
  d.setHours(hour, minute, second, ms);
  return d.getTime();
}

/** ISO-8601 expanded year representation: 0042, -000042, +010000. */
function formatYear(year) {
  if (year < 0) return `-${pad(Math.abs(year), 6)}`;
  if (year > 9999) return `+${pad(year, 6)}`;
  return pad(year, 4);
}

/** ±HH:MM offset of a Date in the host timezone. */
function formatOffset(d) {
  const totalMinutes = -d.getTimezoneOffset();
  const sign = totalMinutes < 0 ? '-' : '+';
  const abs = Math.abs(totalMinutes);
  return `${sign}${pad(Math.floor(abs / 60))}:${pad(abs % 60)}`;
}

/** Zone designator → offset in minutes, or null when no zone was given. */
function parseOffset(zone) {
  if (zone === undefined) return null;
  if (zone === 'Z' || zone === 'z') return 0;

  const sign = zone[0] === '-' ? -1 : 1;
  const digits = zone.slice(1).replace(':', '');
  const hours = Number(digits.slice(0, 2));
  const minutes = digits.length > 2 ? Number(digits.slice(2, 4)) : 0;

  if (hours > 23 || minutes > 59) {
    throw new RangeError(`Invalid UTC offset "${zone}"`);
  }
  return sign * (hours * 60 + minutes);
}

function coerceDate(value) {
  let d;
  if (value instanceof Date) {
    d = value;
  } else if (typeof value === 'number') {
    d = new Date(value);
  } else if (typeof value === 'string') {
    d = parseDate(value);
  } else {
    throw new TypeError(
      'formatDate(date): expected a Date, a timestamp, or an ISO-8601 string'
    );
  }
  if (Number.isNaN(d.getTime())) {
    throw new RangeError('formatDate(date): received an invalid date');
  }
  return d;
}

/* ------------------------------------------------------------------ *
 * Public API
 * ------------------------------------------------------------------ */

/**
 * Format a date as an ISO-8601 string.
 *
 * @param {Date|number|string} date  Date instance, epoch milliseconds, or ISO string.
 * @param {object} [options]
 * @param {'day'|'minute'|'second'|'millisecond'} [options.precision='day']
 *        How much of the time to include.
 * @param {'utc'|'local'} [options.timezone='utc']
 *        Which clock to read the components from.
 * @returns {string} e.g. '2024-02-29' or '2024-02-29T12:34:56.789Z'
 */
export function formatDate(date, options = {}) {
  const d = coerceDate(date);
  const { precision = 'day', timezone = 'utc' } = options;

  if (!PRECISIONS.has(precision)) {
    throw new RangeError(
      `formatDate(date): options.precision must be one of ${[...PRECISIONS].join(', ')}`
    );
  }
  if (timezone !== 'utc' && timezone !== 'local') {
    throw new RangeError("formatDate(date): options.timezone must be 'utc' or 'local'");
  }

  const local = timezone === 'local';
  const year = local ? d.getFullYear() : d.getUTCFullYear();
  const month = (local ? d.getMonth() : d.getUTCMonth()) + 1;
  const day = local ? d.getDate() : d.getUTCDate();
  const hour = local ? d.getHours() : d.getUTCHours();
  const minute = local ? d.getMinutes() : d.getUTCMinutes();
  const second = local ? d.getSeconds() : d.getUTCSeconds();
  const ms = local ? d.getMilliseconds() : d.getUTCMilliseconds();

  let out = `${formatYear(year)}-${pad(month)}-${pad(day)}`;
  if (precision === 'day') return out;

  out += `T${pad(hour)}:${pad(minute)}`;
  if (precision === 'second' || precision === 'millisecond') {
    out += `:${pad(second)}`;
  }
  if (precision === 'millisecond') {
    out += `.${pad(ms, 3)}`;
  }
  out += local ? formatOffset(d) : 'Z';
  return out;
}

/**
 * Parse an ISO-8601 string into a Date.
 *
 * Accepted forms:
 *   YYYY-MM-DD
 *   YYYY-MM-DDTHH
 *   YYYY-MM-DDTHH:mm
 *   YYYY-MM-DDTHH:mm:ss
 *   YYYY-MM-DDTHH:mm:ss.sss      (1-9 fractional digits)
 * each optionally followed by 'Z' or a ±hh / ±hhmm / ±hh:mm offset.
 *
 * @param {string} str
 * @param {object} [options]
 * @param {'utc'|'local'} [options.timezone='utc']
 *        How to interpret values that carry no zone designator.
 * @returns {Date}
 * @throws {TypeError}  if `str` is not a string.
 * @throws {RangeError} if `str` is not a valid ISO-8601 date.
 */
export function parseDate(str, options = {}) {
  if (typeof str !== 'string') {
    throw new TypeError(`parseDate(str): expected a string, received ${typeof str}`);
  }

  const text = str.trim();
  if (text === '') {
    throw new RangeError('parseDate(str): empty string is not a valid ISO-8601 date');
  }

  const { timezone = 'utc' } = options;
  if (timezone !== 'utc' && timezone !== 'local') {
    throw new RangeError("parseDate(str): options.timezone must be 'utc' or 'local'");
  }

  // --- Date only -----------------------------------------------------
  const dateOnly = DATE_RE.exec(text);
  if (dateOnly) {
    const year = Number(dateOnly[1]);
    const month = Number(dateOnly[2]);
    const day = Number(dateOnly[3]);
    assertValidYmd(year, month, day);

    return new Date(
      timezone === 'local'
        ? localMillis(year, month, day)
        : utcMillis(year, month, day)
    );
  }

  // --- Date + time ---------------------------------------------------
  const match = DATE_TIME_RE.exec(text);
  if (!match) {
    throw new RangeError(`parseDate(str): "${str}" is not a valid ISO-8601 date`);
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const hour = Number(match[4]);
  const minute = match[5] === undefined ? 0 : Number(match[5]);
  const second = match[6] === undefined ? 0 : Number(match[6]);
  const millis =
    match[7] === undefined ? 0 : Number(match[7].slice(0, 3).padEnd(3, '0'));

  assertValidYmd(year, month, day);

  if (hour > 24 || minute > 59 || second > 59) {
    throw new RangeError(`parseDate(str): invalid time in "${str}"`);
  }
  if (hour === 24 && (minute !== 0 || second !== 0 || millis !== 0)) {
    throw new RangeError(`parseDate(str): invalid time in "${str}"`);
  }

  const offsetMinutes = parseOffset(match[8]);

  // No zone designator → interpret using the requested timezone.
  if (offsetMinutes === null) {
    return new Date(
      timezone === 'local'
        ? localMillis(year, month, day, hour, minute, second, millis)
        : utcMillis(year, month, day, hour, minute, second, millis)
    );
  }

  // Explicit zone → normalise to UTC.
  const stamp = utcMillis(year, month, day, hour, minute, second, millis);
  return new Date(stamp - offsetMinutes * 60_000);
}

export default { formatDate, parseDate };
```

## Quick reference

| Call | Result |
|---|---|
| `formatDate(new Date('2024-02-29T12:34:56Z'))` | `'2024-02-29'` |
| `formatDate(d, { precision: 'minute' })` | `'2024-02-29T12:34Z'` |
| `formatDate(d, { precision: 'millisecond' })` | `'2024-02-29T12:34:56.789Z'` |
| `formatDate(d, { precision: 'second', timezone: 'local' })` | `'2024-02-29T12:34:56+01:00'` |
| `parseDate('2024-02-29')` | `Date` at `2024-02-29T00:00:00Z` |
| `parseDate('2024-02-29T12:00:00+02:00')` | `Date` at `2024-02-29T10:00:00Z` |
| `parseDate('2024-02-29T12:00:00.5Z')` | `Date` at `...T12:00:00.500Z` |
| `parseDate('2023-02-29')` | throws `RangeError` |

## Design decisions worth knowing

- **UTC by default.** `formatDate` reads UTC components so the same `Date` always produces the same string, regardless of the server's timezone. Opt into local time explicitly.
- **Strict parsing.** `new Date('2024-13-01')` silently becomes 2025-01-01; `parseDate` rejects it. Leap days are validated (`2023-02-29` throws, `2024-02-29` is fine).
- **Years 0–99 are handled correctly** via `setUTCFullYear`/`setFullYear` — `Date.UTC(99, 0, 1)` would otherwise give 1999.
- **Round-tripping works:** `formatDate(parseDate(s), { precision: 'millisecond' })` reproduces the original string for any input that carried an explicit `Z` offset.
- **Errors:** `TypeError` for wrong argument types, `RangeError` for invalid values — so you can distinguish "you called me wrong" from "that date doesn't exist".

# `iso-date.js`

A dependency-free ES module with strict ISO‑8601 parsing and predictable formatting.

```js
/**
 * iso-date.js
 * ---------------------------------------------------------------------------
 * Formatting and parsing of ISO-8601 date strings.
 *
 *   formatDate(date, options?) -> string   // always a valid ISO-8601 string
 *   parseDate(str)            -> Date|null // null when the input is invalid
 *
 * Design notes
 *  - Formatting is done in UTC by default so output is deterministic
 *    (no hidden dependency on the machine's local time zone).
 *  - Parsing is *strict*: only ISO-8601 shapes are accepted, and every
 *    component is range-checked (e.g. 2023-02-30 is rejected).
 *  - A date-only string ("2024-03-15") is interpreted as UTC midnight,
 *    matching the ECMAScript Date.parse() specification.
 */

/* -------------------------------------------------------------------------- *
 * Internal helpers
 * -------------------------------------------------------------------------- */

/**
 * ISO-8601 (extended format) with a few pragmatic extensions:
 *   - "T" or " " as the date/time separator
 *   - fractional seconds with "." or "," and 1-9 digits
 *   - offsets as "Z", "+05:30" or "+0530"
 *   - expanded years ("+002024" / "-000001")
 */
const ISO_RE =
  /^([+-]\d{6}|\d{4})-(\d{2})-(\d{2})(?:[Tt ](\d{2}):(\d{2})(?::(\d{2})(?:[.,](\d{1,9}))?)?(Z|z|[+-]\d{2}:?\d{2})?)?$/;

const PRECISIONS = new Set(['day', 'hour', 'minute', 'second', 'millisecond']);

function pad(value, width = 2) {
  return String(Math.abs(value)).padStart(width, '0');
}

function formatYear(year) {
  if (year >= 0 && year <= 9999) return String(year).padStart(4, '0');
  return (year < 0 ? '-' : '+') + String(Math.abs(year)).padStart(6, '0');
}

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year, month /* 1-12 */) {
  const lengths = [31, isLeapYear(year) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return lengths[month - 1];
}

/** Date.UTC() that also works for years 0-99 (which it would otherwise map to 1900-1999). */
function utcMillis(year, monthIndex, day, hour, minute, second, ms) {
  const t = Date.UTC(year, monthIndex, day, hour, minute, second, ms);
  if (year >= 0 && year < 100) {
    const d = new Date(t);
    d.setUTCFullYear(year);
    return d.getTime();
  }
  return t;
}

/** Offset of `timeZone` (in minutes east of UTC) at the given instant. */
function getTimeZoneOffset(date, timeZone) {
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone, // undefined => the runtime's local zone
    hourCycle: 'h23',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  });

  const parts = {};
  for (const part of dtf.formatToParts(date)) parts[part.type] = part.value;

  let year = Number(parts.year);
  if (parts.era && /^b/i.test(parts.era)) year = 1 - year; // BC -> astronomical year

  const wallClock = utcMillis(
    year,
    Number(parts.month) - 1,
    Number(parts.day),
    Number(parts.hour),
    Number(parts.minute),
    Number(parts.second),
    0
  );

  const truncated = date.getTime() - date.getUTCMilliseconds();
  return Math.round((wallClock - truncated) / 60000);
}

function formatOffset(offsetMinutes) {
  if (offsetMinutes === 0) return 'Z';
  const sign = offsetMinutes < 0 ? '-' : '+';
  const abs = Math.abs(offsetMinutes);
  return `${sign}${pad(Math.floor(abs / 60))}:${pad(abs % 60)}`;
}

/** Coerce Date | number (epoch ms) | ISO string into a valid Date, or null. */
function toDate(value) {
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value;
  if (typeof value === 'number') {
    const d = new Date(value);
    return Number.isNaN(d.getTime()) ? null : d;
  }
  if (typeof value === 'string') return parseDate(value);
  return null;
}

/* -------------------------------------------------------------------------- *
 * Public API
 * -------------------------------------------------------------------------- */

/**
 * Format a date as an ISO-8601 string.
 *
 * @param {Date|number|string} date  A Date, an epoch-millisecond timestamp,
 *                                   or an ISO-8601 string.
 * @param {object}  [options]
 * @param {'day'|'hour'|'minute'|'second'|'millisecond'} [options.precision='millisecond']
 *        How much of the time to include.
 * @param {string}  [options.timeZone='UTC']
 *        An IANA time-zone name (e.g. 'Europe/Berlin'), or 'local' for the
 *        system time zone.
 * @returns {string} e.g. "2024-03-15T14:30:00.000Z"
 * @throws {TypeError}  if `date` cannot be interpreted as a valid date.
 * @throws {RangeError} if `precision` or `timeZone` is invalid.
 */
export function formatDate(date, options = {}) {
  const d = toDate(date);
  if (!d) {
    throw new TypeError(
      'formatDate(date): expected a valid Date, epoch-millisecond number, or ISO-8601 string'
    );
  }

  const { precision = 'millisecond', timeZone = 'UTC' } = options;
  if (!PRECISIONS.has(precision)) {
    throw new RangeError(
      `formatDate(date, { precision }): expected one of ${[...PRECISIONS].join(', ')}`
    );
  }

  const offsetMinutes = getTimeZoneOffset(d, timeZone === 'local' ? undefined : timeZone);
  const local = new Date(d.getTime() + offsetMinutes * 60000);

  let out = `${formatYear(local.getUTCFullYear())}-${pad(local.getUTCMonth() + 1)}-${pad(
    local.getUTCDate()
  )}`;
  if (precision === 'day') return out;

  out += `T${pad(local.getUTCHours())}:${pad(local.getUTCMinutes())}`;
  if (precision === 'hour') return out;

  out += `:${pad(local.getUTCSeconds())}`;
  if (precision === 'second') return out;

  out += `.${pad(local.getUTCMilliseconds(), 3)}${formatOffset(offsetMinutes)}`;
  return out;
}

/**
 * Parse an ISO-8601 string into a Date.
 *
 * Accepted shapes:
 *   "2024-03-15"
 *   "2024-03-15T10:20"
 *   "2024-03-15T10:20:30"
 *   "2024-03-15T10:20:30.123Z"
 *   "2024-03-15T10:20:30+05:30"   (also "+0530")
 *
 * @param {string} str
 * @returns {Date|null} The parsed date, or null if `str` is not a valid
 *                     ISO-8601 date string.
 */
export function parseDate(str) {
  if (typeof str !== 'string') return null;

  const m = ISO_RE.exec(str.trim());
  if (!m) return null;

  const year = Number(m[1]); // handles "+002024" / "-000001" as well
  const month = Number(m[2]);
  const day = Number(m[3]);
  const hour = m[4] === undefined ? 0 : Number(m[4]);
  const minute = m[5] === undefined ? 0 : Number(m[5]);
  const second = m[6] === undefined ? 0 : Number(m[6]);
  const fraction = m[7];
  const offset = m[8];

  // Range checks (reject things like 2023-02-30 or 25:00).
  if (month < 1 || month > 12) return null;
  if (day < 1 || day > daysInMonth(year, month)) return null;
  if (hour > 23 || minute > 59 || second > 59) return null;

  let ms = 0;
  if (fraction !== undefined) ms = Number((fraction + '000').slice(0, 3));

  let offsetMinutes = 0;
  if (offset && offset !== 'Z' && offset !== 'z') {
    const sign = offset[0] === '-' ? -1 : 1;
    const digits = offset.slice(1).replace(':', '');
    const offsetHours = Number(digits.slice(0, 2));
    const offsetMins = Number(digits.slice(2, 4));
    if (offsetHours > 23 || offsetMins > 59) return null;
    offsetMinutes = sign * (offsetHours * 60 + offsetMins);
  }

  const timestamp =
    utcMillis(year, month - 1, day, hour, minute, second, ms) - offsetMinutes * 60000;

  const result = new Date(timestamp);
  return Number.isNaN(result.getTime()) ? null : result;
}

/**
 * Convenience predicate: is `str` a valid ISO-8601 date string?
 *
 * @param {string} str
 * @returns {boolean}
 */
export function isValidISODate(str) {
  return parseDate(str) !== null;
}

export default { formatDate, parseDate, isValidISODate };
