  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year, month) {
  return month === 2 && isLeapYear(year) ? 29 : DAYS_PER_MONTH[month - 1];
}

function pad(value, width = 2) {
  return String(value).padStart(width, '0');
}

/**
 * Format a date as an ISO-8601 string.
 *
 * @param {Date|number|string} date  A Date, a timestamp (ms), or an ISO-8601 string.
 * @param {{dateOnly?: boolean, local?: boolean}} [options]
 *        dateOnly → "YYYY-MM-DD"; local → render in the local time zone (no "Z").
 * @returns {string} e.g. "2024-01-15T10:30:00.000Z"
 */
export function formatDate(date, options = {}) {
  const { dateOnly = false, local = false } = options ?? {};
  const value = toDate(date);

  if (value === null || Number.isNaN(value.getTime())) {
    throw new TypeError('formatDate: expected a valid Date, timestamp, or ISO-8601 string');
  }

  if (dateOnly) {
    return value.toISOString().slice(0, 10);
  }

  if (local) {
    return (
      `${pad(value.getFullYear(), 4)}-${pad(value.getMonth() + 1)}-${pad(value.getDate())}` +
      `T${pad(value.getHours())}:${pad(value.getMinutes())}:${pad(value.getSeconds())}` +
      `.${pad(value.getMilliseconds(), 3)}`
