 * Parse an ISO-8601 string into a Date.
 *
 * @param {string} str e.g. "2024-01-15", "2024-01-15T10:30:00Z", "2024-01-15T10:30:00+02:00"
 * @returns {Date}
 * @throws {TypeError} if `str` is not a string
 * @throws {RangeError} if `str` is not a valid ISO-8601 date
 */
