  if (typeof str !== 'string') {
    throw new TypeError(`parseDate: expected a string, received ${typeof str}`);
  }

  const value = str.trim();
  const match = ISO_8601_RE.exec(value);

  if (!match) {
    throw new RangeError(`parseDate: "${str}" is not a valid ISO-8601 date string`);
  }

