    ,
    yearText, monthText, dayText,
    hourText, minuteText, secondText, fractionText,
    zulu, offsetSign, offsetHourText, offsetMinuteText,
  ] = match;

  const year = Number(yearText);
  const month = Number(monthText);
  const day = Number(dayText);

  if (month < 1 || month > 12) {
    throw new RangeError(`parseDate: month out of range in "${str}"`);
  }
  if (day < 1 || day > daysInMonth(year, month)) {
    throw new RangeError(`parseDate: day out of range in "${str}"`);
  }

  const hasTime = hourText !== undefined;
  const hour = hasTime ? Number(hourText) : 0;
  const minute = hasTime ? Number(minuteText) : 0;
  const second = hasTime && secondText !== undefined ? Number(secondText) : 0;
  const millisecond = fractionText ? Number(fractionText.slice(0, 3).padEnd(3, '0')) : 0;

  if (hasTime) {
    if (hour > 24 || minute > 59 || second > 59) {
      throw new RangeError(`parseDate: time out of range in "${str}"`);
    }
    // ISO-8601 allows 24:00:00 as the end of the day, but nothing beyond that.
    if (hour === 24 && (minute !== 0 || second !== 0 || millisecond !== 0)) {
      throw new RangeError(`parseDate: invalid 24:00 time in "${str}"`);
    }
