  let offsetMinutes = 0;

  if (offsetSign !== undefined) {
    const offsetHours = Number(offsetHourText);
    const offsetMins = Number(offsetMinuteText);

    if (offsetHours > 23 || offsetMins > 59) {
      throw new RangeError(`parseDate: UTC offset out of range in "${str}"`);
    }
    offsetMinutes = (offsetHours * 60 + offsetMins) * (offsetSign === '+' ? 1 : -1);
