/**
 * iso-date.js
 * ---------------------------------------------------------------------------
 * Formatting and parsing helpers for ISO-8601 dates.
 *
 * Supported on input (parseDate):
 *   2024                     reduced precision (year)
 *   2024-03                  year + month
 *   2024-03-15               calendar date
 *   2024-074                 ordinal date (day of year)
 *   2024-W11-5               week date
 *   2024-03-15T10:30         date + time (no offset => interpreted as UTC)
 *   2024-03-15T10:30:45.123Z date + time + fraction + offset
 *   2024-03-15T10:30:45+05:30 / +0530 / +05 / -08:00
 *   +002024-03-15            expanded (6-digit) year
 *
 * Output (formatDate) is always UTC, extended format:
 *   2024-03-15T10:30:45.123Z
 *
 * Only the *extended* representation is accepted on input; the basic
 * (no-separator) form such as "20240315" is intentionally not supported.
 */

/* -------------------------------------------------------------------------- */
/* Constants                                                                  */
/* -------------------------------------------------------------------------- */

const MS_PER_MINUTE = 60_000;
const MS_PER_DAY = 86_400_000;

const MONTH_LENGTHS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

/**
 * Grammar for the extended ISO-8601 forms listed above.
 * Named capture groups keep the parsing code readable.
 */
const ISO_PATTERN = new RegExp(
  [
    '^(?<year>[+-]\\d{6}|\\d{4})',
    '(?:-(?<month>\\d{2})(?:-(?<day>\\d{2}))?',
    '|-(?<ordinal>\\d{3})',
    '|-W(?<week>\\d{2})-(?<weekday>\\d))?',
    '(?:[T ](?<hour>\\d{2})',
    '(?::(?<minute>\\d{2})',
    '(?::(?<second>\\d{2})(?:[.,](?<fraction>\\d+))?)?)?',
    '(?<offset>[Zz]|[+-]\\d{2}(?::?\\d{2})?)?)?$',
  ].join('')
);

/* -------------------------------------------------------------------------- */
/* Internal helpers                                                           */
/* -------------------------------------------------------------------------- */

const pad2 = (n) => String(n).padStart(2, '0');

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year, month) {
  if (month === 2 && isLeapYear(year)) return 29;
  return MONTH_LENGTHS[month - 1];
}

/** ISO weekday: Monday = 1 ... Sunday = 7. */
function isoWeekday(date) {
  return ((date.getUTCDay() + 6) % 7) + 1;
}

/** Number of ISO weeks (52 or 53) in the given year. */
function isoWeeksInYear(year) {
  const jan1 = makeUTC(year, 1, 1);
  const dow = isoWeekday(jan1);
  return dow === 4 || (isLeapYear(year) && dow === 3) ? 53 : 52;
}

/**
 * Build a Date from calendar parts, interpreted as UTC.
 * Uses setUTCFullYear so that years 0-99 are not remapped to 1900-1999.
 */
function makeUTC(year, month, day, hours = 0, minutes = 0, seconds = 0, ms = 0) {
  const d = new Date(0);
  d.setUTCFullYear(year, month - 1, day);
  d.setUTCHours(hours, minutes, seconds, ms);
  return d;
}

/** Convert a UTC offset ("Z", "+05:30", "-0800", "+05") to signed minutes. */
function parseOffset(offset) {
  if (!offset) return 0;
  if (offset === 'Z' || offset === 'z') return 0;

  const sign = offset[0] === '-' ? -1 : 1;
  const body = offset.slice(1).replace(':', '');
  const hours = Number(body.slice(0, 2));
  const minutes = body.length > 2 ? Number(body.slice(2, 4)) : 0;

  if (hours > 23 || minutes > 59) {
    throw new RangeError(`Invalid UTC offset: "${offset}"`);
  }
  return sign * (hours * 60 + minutes);
}

/** Format a year as 4 digits, or as an expanded 6-digit year when needed. */
function formatYear(year) {
  if (year >= 0 && year <= 9999) return String(year).padStart(4, '0');
  const sign = year < 0 ? '-' : '+';
  return sign + String(Math.abs(year)).padStart(6, '0');
}

/** Coerce the accepted input types of formatDate() into a valid Date. */
function toDate(value) {
  if (value instanceof Date) {
    if (Number.isNaN(value.getTime())) {
      throw new RangeError('formatDate(date): received an Invalid Date');
    }
    return value;
  }
  if (typeof value === 'number') {
    const d = new Date(value);
    if (Number.isNaN(d.getTime())) {
      throw new RangeError('formatDate(date): received an invalid timestamp');
    }
    return d;
  }
  if (typeof value === 'string') {
    return parseDate(value); // strict ISO-8601 parsing
  }
  throw new TypeError(
    'formatDate(date): expected a Date, a timestamp, or an ISO-8601 string'
  );
}

/* -------------------------------------------------------------------------- */
/* Public API                                                                 */
/* -------------------------------------------------------------------------- */

/**
 * Format a date as an ISO-8601 string in UTC.
 *
 * @param {Date|number|string} date  Date, epoch-milliseconds, or ISO-8601 string.
 * @param {object}  [options]
 * @param {boolean} [options.dateOnly=false]  Return "YYYY-MM-DD" only.
 * @param {'milliseconds'|'seconds'|'minutes'} [options.precision='milliseconds']
 * @returns {string} e.g. "2024-03-15T10:30:45.123Z"
 * @throws {TypeError|RangeError} on invalid input.
 */
export function formatDate(date, options = {}) {
  const { dateOnly = false, precision = 'milliseconds' } = options;
  const d = toDate(date);

  const year = formatYear(d.getUTCFullYear());
  const month = pad2(d.getUTCMonth() + 1);
  const day = pad2(d.getUTCDate());

  if (dateOnly) return `${year}-${month}-${day}`;

  const hours = pad2(d.getUTCHours());
  const minutes = pad2(d.getUTCMinutes());
  const seconds = pad2(d.getUTCSeconds());

  if (precision === 'minutes') return `${year}-${month}-${day}T${hours}:${minutes}Z`;
  if (precision === 'seconds') return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}Z`;

  const ms = String(d.getUTCMilliseconds()).padStart(3, '0');
  return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}.${ms}Z`;
}

/**
 * Parse an ISO-8601 string into a Date.
 *
 * A missing UTC offset is interpreted as UTC (not as local time), so the
 * function is deterministic regardless of the host time zone.
 *
 * @param {string} str  ISO-8601 string.
 * @returns {Date}
 * @throws {TypeError}  if `str` is not a string.
 * @throws {RangeError} if `str` is malformed or denotes a non-existent date.
 */
export function parseDate(str) {
  if (typeof str !== 'string') {
    throw new TypeError(`parseDate(str): expected a string, received ${typeof str}`);
  }

  const text = str.trim();
  if (text === '') {
    throw new RangeError('parseDate(str): received an empty string');
  }

  const match = ISO_PATTERN.exec(text);
  if (!match) {
    throw new RangeError(`parseDate(str): "${str}" is not a valid ISO-8601 string`);
  }

  const g = match.groups;
  const year = Number(g.year); // handles "+002024" -> 2024 and "-000001" -> -1

  let month = 1;
  let day = 1;

  if (g.ordinal !== undefined) {
    // Ordinal date: 2024-074 -> 2024-03-14
    const ordinal = Number(g.ordinal);
    const daysInYear = isLeapYear(year) ? 366 : 365;
    if (ordinal < 1 || ordinal > daysInYear) {
      throw new RangeError(
        `parseDate(str): "${str}" has an out-of-range day of year (${ordinal})`
      );
    }
    let rest = ordinal;
    month = 1;
    while (rest > daysInMonth(year, month)) {
      rest -= daysInMonth(year, month);
      month += 1;
    }
    day = rest;
  } else if (g.week !== undefined) {
    // Week date: 2024-W11-5 -> 2024-03-15
    const week = Number(g.week);
    const weekday = Number(g.weekday);
    if (weekday < 1 || weekday > 7) {
      throw new RangeError(
        `parseDate(str): "${str}" has an out-of-range weekday (${weekday})`
      );
    }
    const maxWeeks = isoWeeksInYear(year);
    if (week < 1 || week > maxWeeks) {
      throw new RangeError(
        `parseDate(str): "${str}" has an out-of-range week (${week}, max ${maxWeeks})`
      );
    }
    // Jan 4 always falls in ISO week 1.
    const jan4 = makeUTC(year, 1, 4);
    const week1Monday = new Date(jan4.getTime() - (isoWeekday(jan4) - 1) * MS_PER_DAY);
    const target = new Date(
      week1Monday.getTime() + ((week - 1) * 7 + (weekday - 1)) * MS_PER_DAY
    );
    month = target.getUTCMonth() + 1;
    day = target.getUTCDate();
  } else {
    month = g.month !== undefined ? Number(g.month) : 1;
    day = g.day !== undefined ? Number(g.day) : 1;

    if (month < 1 || month > 12) {
      throw new RangeError(`parseDate(str): "${str}" has an invalid month (${month})`);
    }
    const maxDay = daysInMonth(year, month);
    if (day < 1 || day > maxDay) {
      throw new RangeError(
        `parseDate(str): "${str}" has an invalid day (${day}) for month ${month}`
      );
    }
  }

  let hours = 0;
  let minutes = 0;
  let seconds = 0;
  let ms = 0;

  if (g.hour !== undefined) {
    hours = Number(g.hour);
    minutes = g.minute !== undefined ? Number(g.minute) : 0;
    seconds = g.second !== undefined ? Number(g.second) : 0;
    if (g.fraction !== undefined) {
      ms = Number((g.fraction + '000').slice(0, 3)); // truncate to milliseconds
    }

    if (hours > 24 || minutes > 59 || seconds > 60) {
      throw new RangeError(`parseDate(str): "${str}" has an invalid time`);
    }
    if (hours === 24 && (minutes !== 0 || seconds !== 0 || ms !== 0)) {
      throw new RangeError(
        `parseDate(str): "${str}" may only use 24:00:00 as end-of-day`
      );
    }
    if (seconds === 60) {
      // Leap second: represent it as the last millisecond before the next minute.
      seconds = 59;
      ms += 1000;
    }
  }

  const offsetMinutes = parseOffset(g.offset);
  const local = makeUTC(year, month, day, hours, minutes, seconds, ms);
  return new Date(local.getTime() - offsetMinutes * MS_PER_MINUTE);
}

/**
 * Convenience predicate: does `str` parse as a valid ISO-8601 date?
 *
 * @param {string} str
 * @returns {boolean}
 */
export function isValidISODate(str) {
  try {
    parseDate(str);
    return true;
  } catch {
    return false;
  }
}
