      return null; // e.g. a wall-clock time skipped by a DST transition
    }
    return d;
  }

  // Date-only (UTC) or an explicit offset: verify in UTC terms.
  const d = new Date(wallMillis - offsetMinutes * 60_000);
  if (
    Number.isNaN(d.getTime()) ||
    d.getUTCFullYear() !== year ||
    d.getUTCMonth() !== month - 1 ||
    d.getUTCDate() !== day ||
    d.getUTCHours() !== hour ||
    d.getUTCMinutes() !== minute ||
    d.getUTCSeconds() !== second
