  const d = new Date(0);
  d.setUTCFullYear(year, month - 1, day);
  d.setUTCHours(hour, minute, second, millisecond);
  return d.getTime();
}

/** Epoch ms for the given components interpreted as local time (handles years < 100). */
function localMs(year, month, day, hour, minute, second, millisecond) {
  const d = new Date(0);
  d.setFullYear(year, month - 1, day);
  d.setHours(hour, minute, second, millisecond);
  return d.getTime();
}

