    throw new RangeError(`parseDate(str): "${str}" has an invalid month`);
  }
  if (day < 1 || day > daysInMonth(year, month)) {
    throw new RangeError(`parseDate(str): "${str}" has an invalid day for that month`);
  }
  if (hour > 23 || minute > 59 || second > 59) {
    throw new RangeError(`parseDate(str): "${str}" has an invalid time`);
  }

  let timestamp;
  if (zone) {
    const offsetMinutes = parseOffset(zone);
    timestamp =
      utcMs(year, month, day, hour, minute, second, millisecond) - offsetMinutes * 60_000;
