    timestamp = localMs(year, month, day, hour, minute, second, millisecond);
  } else {
    timestamp = utcMs(year, month, day, 0, 0, 0, 0);
  }

  const result = new Date(timestamp);
  if (Number.isNaN(result.getTime())) {
    throw new RangeError(`parseDate(str): "${str}" is not a valid ISO-8601 date`);
  }
